// Generated from handbook release source by work/handbook-import/build_handbook_exercises.py.
export const handbookExercises = {"0.1":{"prompt":"**START-01 · День за днем.** Навчальний офер чохлів у США: покупець платить $28, а баєру зараховують $9 за викуп. Баєр витрачає $32 на рекламу й $8 на матеріали. Покупці платять магазину. Звіти відкриваються по черзі.\n\n1. **Збір:** 12 прийнятих заявок. Намалюй три платежі й запиши суму, яка вже пішла з бюджету.\n\n2. **Обробка:** 6 підтверджено, 3 відхилено, 3 ще відкриті. Якого статусу бракує для доходу? Чи можна фінансувати повтор із грошей цього тесту до виплати?\n\n3. **Фінал:** зараховано 5 викупів. Порахуй нарахування, результат і суму власних витрат до виплати. Що зміниться, якщо зарахують чотири?","exercises":[{"id":"START-01","types":["День за днем"],"states":"- Збір: 12 прийнятих заявок, реклама 32, матеріали 8, ставка 9 за зарахований викуп. - Обробка: 6 підтверджено, 3 відхилено, 3 ще відкриті; виплати немає. - Фінал: 5 зарахованих викупів; потім сценарій із 4.","input":"- Збір: зістав три пари платник-одержувач; число витрат, допуск 0. - Обробка: вибір статусу для виплати та вибір «можна / не можна» фінансувати повтор. - Фінал: числа нарахування, результату, коштів до виплати й результату за 4 дій; допуск 0.","answer":"[40, зарахований викуп, не можна, 45, 5, 40, -4]","decision":"три правильні потоки і правильний статус","evidence":"точні суми","nextStep":"внести в журнал дату виплати","wrongAnswer":"6 × 9; шість — підтвердження, а оплачують викуп."}]},"0.2":{"prompt":"**START-02 · Діалог + Порахуй.** Баєр працює напряму з магазином. У навчальному офері з продажу чохлів у США ціна для покупця $29, а договір дає $9 за зарахований викуп. Магазин бачить п’ять викупів, але у фінальному звіті їх чотири. У журналі доставки Q-105 має статус «викуплено» о 16:00. Період та часовий пояс однакові.\n\n1. Порахуй поточне нарахування. Покупець заплатив магазину. Запиши, хто платить рекламній платформі та хто виплачує винагороду баєру.\n\n2. Обери першу репліку. **А.** «Можете додати п’ятий викуп?» **Б.** «Q-105 є в журналі доставки о 16:00, але його немає у фінальному звіті за той самий період. Підкажіть статус у реєстрі нарахувань і правило, за яким цей запис включають». **В.** «Я уточню у партнерської мережі».\n\n3. Перед наступним вибором прочитай лише відповідь на свою репліку. Для А магазин просить навести ID і звіт. Для Б магазин відповідає, що ще не знаходить Q-105 у реєстрі. Для В команда нагадує, що угода пряма. Обери наступний крок: попросити технічного власника простежити Q-105 від доставки до реєстру, замінити креатив або записати $45 як остаточну виплату. Якщо почав із А або В, спочатку повтори конкретний запит магазину з ID.","exercises":[{"id":"START-02","types":["Діалог","Порахуй"],"states":"[картка прямої угоди, журнали доставки та виплати, три репліки, відповідь лише на вибрану репліку, три наступні кроки]","input":"[number: нарахування USD, text: платники й одержувачі, choice: перша репліка, choice: наступний крок]","answer":"[36, баєр платформі та магазин баєру, Б, технічна звірка Q-105]","decision":"лише чотири зарахування","evidence":"Q-105 і час та звіт","nextStep":"технічна звірка після предметного запиту","wrongAnswer":"В — мережі немає в прямій угоді, тому потрібний запис перевіряє магазин."}]},"0.3":{"prompt":"**START-03 · Оціни офер + Порахуй.** Команда шукає офер з оплатою за зараховане встановлення. Вибери одну картку й поясни, чому дві інші не підходять. Для кожної картки вибери модель й оплачувану дію, а потім введи підтверджену суму. Якщо для повного підрахунку бракує даних, назви поле.\n\nУсі три приклади вигадані. A і B залучають до сервісів, які заробляють на платних планах. Заповнення форми й встановлення безплатні для користувача. Ставки за ці дії сплачує рекламодавець зі свого бюджету.\n\n| Офер | Умови й записи |\n|---|---|\n| A | $6 за зараховану DOI-реєстрацію. Є 12 форм, 8 підтверджень через лист і 1 дубль серед підтверджень |\n| B | $3 за зараховане встановлення. 60 завантажень, 48 установлень, 42 зараховано |\n| C | $5 за кожного з 4 зарахованих покупців плюс 5% від виручки після повернень. Ціна покупки $200. Виручка до повернень $800, повернень у звіті немає окремим числом |","exercises":[{"id":"START-03","types":["Оціни офер","Порахуй"],"states":"- Картки A, B, C та звіти показано одночасно. - Обмеження задачі: застосунок має оплачувати саме зараховане встановлення.","input":"- choice: [A, B, C]; причина відмови для решти. - choice: модель і оплачуваний статус кожної картки. - number: нарахування A, B і підтверджена фіксована частина C; допуск 0. - choice: [сума повернень, витрати на рекламу, покази].","answer":"[B, CPL з DOI, CPI, Hybrid, 42, 126, 20, сума повернень]","decision":"B та правильна класифікація","evidence":"зараховані статуси й точні суми","nextStep":"запросити базу після повернень","wrongAnswer":"60 для C; базу відсотка до повернень підставлено без доказу."}]},"0.4":{"prompt":"**START-04 · Оціни офер.** Ти готуєш Meta Ads. A: Чехія, підставки для ноутбука, Meta Ads письмово дозволено, чеська форма та доставка підтверджені, у навчальній картці є запис про перевірку допуску. B: Польща, цифровий курс із польською сторінкою, але угода дозволяє тільки пошук. C: Словаччина, фізичний товар, Meta Ads письмово дозволено, продавець поки доставляє лише в Чехію. Обери одну картку для підготовки, назви причини відмови та наступну перевірку для кожної з двох інших.","exercises":[{"id":"START-04","types":["Оціни офер"],"states":"- Показати три картки й зазначити, що заплановано Meta Ads.","input":"- choice: [A, B, C] - choice: причина для кожного відхиленого офера; джерело або виконання. - text: наступна перевірка для B та C.","answer":"[A, B: джерело, C: виконання]","decision":"A","evidence":"коректні причини для B і C","nextStep":"запросити письмовий допуск джерела та підтвердження доставки","wrongAnswer":"B, бо сторінка локалізована; угода дозволяє лише пошук."}]},"0.5":{"prompt":"**START-05 · День за днем + Діалог.** Для тесту чохлів ти готовий втратити до $90. Матеріали коштують $20, трекер $10. Усі ці витрати й реклама оплачуються до виплати. Партнер пропонує передоплатити «гарантоване зарахування» й відмовляється дати договір. На першому екрані бачиш тільки межу втрат $90 та супутні $30. Введи межу реклами й касову потребу. На другому екрані відкривається пропозиція передоплати. Потім обери репліку партнеру: «Переказую зараз» або «Спочатку надішли договір і правила зарахування». Якщо партнер повторно відмовився, обери «відкласти» або «переказати». Запиши, які докази попросиш і яка подія змусить поставити рекламу на паузу, якщо офер пройде перевірку.","exercises":[{"id":"START-05","types":["День за днем","Діалог"],"states":"[ліміт 90, матеріали 20, трекер 10, передоплата без договору]","input":"[number: реклама (допуск 0), number: касова потреба (допуск 0), choice: переказати зараз або запросити договір; після повторної відмови: відкласти або переказати, text: доказ і тригер паузи]","answer":"[60, 90, запросити договір, відкласти]","decision":"відкласти переказ","evidence":"60 і 90","nextStep":"запросити договір і визначити паузу за спостережуваним фактом","wrongAnswer":"90 на рекламу; загалом вийде 120."}]},"0.6":{"prompt":"**START-06 · Пари + Знаменник.** Офер підставок має 25 прийнятих заявок, 10 зарахованих підтверджень і 6 викупів із підтверджених. У картці зазначено холд від дати підтвердження, а в команді питають про розбіжність у реєстрах. Зістав «апрув», «викуп» і «холд» із джерелами доказу. Вибери базу для обох часток і напиши, що потрібно перед висновком про шейв.","exercises":[{"id":"START-06","types":["Пари","Знаменник"],"states":"[картка і звіт з 25 прийнятими, 10 підтвердженнями і 6 викупами]","input":"[pairs: три терміни і документи, drag: чисельник і знаменник двох часток, text: доказ для розбіжності]","answer":"[апрув: реєстр приймання та підтверджень, викуп: записи доставки, холд: картка виплати, 10/25, 6/10]","decision":"правильні пари","evidence":"правильні бази","nextStep":"звірка конкретних ID, періоду і правил","wrongAnswer":"6/25 як викуп від підтверджених; це частка від усіх прийнятих."}]},"final0":{"prompt":"**START-07 · Збери кампанію + Порахуй.** Обидві картки вигадані. Вони призначені для вправи з першої підготовки, а не для запуску.\n\n| Поле | A. Мовний застосунок | B. Мовний застосунок |\n|---|---|---|\n| Продукт і GEO | Курс у застосунку, Чехія, чеська сторінка й підтримка | Курс у застосунку, Чехія, чеська сторінка й підтримка |\n| Ціна для покупця | $22 (≈480 CZK, покупець платить у чеських кронах) за місяць | $22 за місяць, оплата в місцевій валюті |\n| Виплата баєру і дія | $10 за першу оплачену й зараховану підписку після перевірки повернень | $12 за першу оплачену й зараховану підписку після перевірки повернень |\n| Капа | До 8 зарахувань за добу | До 8 зарахувань за добу |\n| Обробка | Журнал партнера показує оплату та фінальний статус після 7 днів перевірки повернень | Той самий порядок обробки |\n| Холд | 14 календарних днів від зарахування | 14 календарних днів від зарахування |\n| Джерело | Meta Ads письмово зазначено; у навчальній картці є підтвердження перевірки допуску | Лише пошук. Менеджер написав «Meta, мабуть, підійде» |\n| Дублі | Повторну оплату тієї самої підписки не зараховують як першу | Те саме правило |\n\nТвоя межа втрат — $120, матеріали коштують $20, сервіс $10. Усі витрати відбуваються до виплати. Інших витрат у вправі немає.\n\n- Обери офер для підготовки й назви причину відмови від іншого.\n\n- Запиши оплачувану дію, потрібний запис у звіті й три грошові потоки.\n\n- Порахуй максимум рекламних витрат, касову потребу при повному використанні ліміту й кількість зарахованих підписок для покриття всіх витрат за обраним офером.\n\n- Назви три моменти в календарі та запиши запит менеджеру щодо B. Уточни, чи можна запустити B на $10 до відповіді.\n\nПеред здачею пройди очима кожен підпис до суми. Максимум на рекламу — це лише частина ліміту. Касова потреба — гроші, які треба мати до виплати. Кількість зарахувань для покриття витрат — умовний поріг. Вона ще не показує, що тест його досягне. У своєму висновку назви кожне число так, щоб тімлід міг перенести його в потрібний рядок плану.\n\n### Заповни бланк здачі\n\nСпочатку склади чернетку однієї кампанії для картки A. Перетягни картки «ціль», «GEO», «подія», «сторінка» й «матеріал» до трьох колонок: кампанія, група оголошень, оголошення. На папері розпиши їх під трьома заголовками. Обери ціль із трьох варіантів: трафік, залучення або продажі. Доступні події в тренажері: перегляд сторінки, реєстрація і перша успішна оплата. Запиши ціль і подію, на яку має працювати кампанія, та поясни, як у фінальному звіті партнерка підтвердить зарахування. У цьому навчальному брифі власник надає доступ до сигналу оплати. Робочі назви в тренажері умовні.\n\n| Рівень чернетки | Що заповнити |\n|---|---|\n| Кампанія | Ціль, загальна межа витрат, умовна назва |\n| Група оголошень | Чехія, узгоджений канал, подія оптимізації, дата контролю |\n| Оголошення | Один правдивий матеріал, чеська сторінка, мітка тесту |\n| Перевірка | Статус контрольного переходу й оплати, підтвердження джерела, рішення про готовність |\n\nВведи в бланк умовний запис QA-07: сторінка відкрилася і тестова оплата є в журналі продавця, але сигнал оплати не видно у джерелі, вибраному для кампанії. Зафіксуй, чи можна затвердити чернетку, хто має розібратися з подією та який результат повторного тесту дасть підставу продовжити.\n\nПеренеси бланк на аркуш. Заповнюй рядки в цьому порядку. Коли пишеш доказ, указуй назву поля у брифі або картці. Коли пишеш дію, використовуй дієслово зі статусу в звіті.\n\n| Рядок | Що вписати |\n|---|---|\n| Відбір | Офер, який беру у підготовку. Поле, за яким відкладаю інший |\n| Оплачувана дія | Що саме має відбутися. Що потрібно дочекатися після дії |\n| Доказ | Назва звіту й статус, який має з’явитися |\n| Грошові потоки | Три пари платник — одержувач із поясненням, за що платять |\n| Бюджет | Ліміт, супутні витрати, залишок на рекламу й кошти до виплати |\n| Поріг | Скільки зарахувань треба для покриття всіх витрат при повному спенді |\n| Календар | Коли витрачаємо, коли виникає нарахування й коли гроші можна використати |\n| Запит | Кому пишу, який документ прошу і що роблю до відповіді |\n\nДля фінального рішення достатньо короткої записки. Почни з обраного офера й причини. Далі додай статус для виплати й максимум витрат. Заверши питанням, яке лишилося відкритим. Не підміняй ним рішення щодо другої картки. Якщо бачиш суперечність, прямо напиши, який запис має змінитися до витрат. Після першої спроби відкрий ключ і познач кожен рядок, який потребує виправлення.\n\nОкремо зроби контрольну перевірку на капу. У картці обмеження вказано на добу. Порівняй його з кількістю дій для покриття витрат. Якщо поріг вищий за добовий ліміт, додай цю умову в нотатки до тесту. Для фіналу достатньо показати арифметичне обмеження. Планувати рекламні дні або робити висновок про окупність за цих даних зарано. Напиши висновок одним реченням і підпиши добу як одиницю для капи.","exercises":[{"id":"START-07","types":["Збери кампанію","Порахуй"],"states":"[картки A і B, канал Meta Ads, ліміт 120, матеріали 20, сервіс 10]","input":"[choice: A або B, choice: причина відмови, text: дія і джерело доказу, pairs: платники й одержувачі, number: межа реклами (допуск 0), number: каса (допуск 0), number: кількість дій (допуск 0), choice: чи вистачить однієї доби за капою, text: календар і запит, sort: картки за трьома рівнями, text: ціль і подія, text: блокер QA-07]","answer":"[A, B обмежено пошуком, зарахована перша оплата після перевірки, 90, 120, 12, не вистачить однієї доби, не витрачати до письмового підтвердження, продажі, перша успішна оплата, QA-07 на паузі]","decision":"A","evidence":"картка і звіт","nextStep":"попросити письмово підтвердити джерело і не витрачати до звірки","wrongAnswer":"120 на рекламу; загалом витрати вийдуть 150."}]},"1.1":{"prompt":"**BASE-01 · Оціни офер + Діалог.** Команда готує Meta Ads для магазину підставок під ноутбук у Чехії. Покупець платить $29 (≈630 CZK, покупець платить у чеських кронах) при отриманні. Усі три пропозиції вигадані.\n\n| Поле | A | B | C |\n|---|---|---|---|\n| Продукт і GEO | Підставка, Чехія, чеська сторінка | Підставка, Чехія, чеська сторінка | Підставка, Чехія, чеська сторінка |\n| Ціна для покупця | $29 | $29 | $29 |\n| Виплата баєру і дія | $12 за зараховане підтвердження | $9 за зараховане підтвердження | $14 за викуп |\n| Капа | 10 зарахувань на добу | 10 зарахувань на добу | 10 викупів на добу |\n| Обробка | До двох робочих днів | До двох робочих днів | Строк фінального статусу невідомий |\n| Холд | 14 днів від підтвердження | 14 днів від підтвердження | Початок відліку невідомий |\n| Джерело | Лише пошук | Meta Ads письмово дозволено | Meta Ads письмово дозволено |\n| Дублі | Повтор заявки відсіюють | Повтор заявки відсіюють | Повтор замовлення відсіюють |\n| Доказ зарахування | Реєстр з ID | Реєстр з ID | Реєстр викупу не надають |\n\nОбери одну картку для підготовки. Для двох інших назви причину відмови. Перенеси вісім основних полів обраної картки у свій шаблон.\n\nПісля вибору B менеджер каже: «Холд 14 днів, далі все стандартно». Обери репліку.\n\n- **1.** «Записую, що рівно через 14 днів гроші будуть на балансі банку».\n\n- **2.** «Уточни мінімальну суму, календар переказу і де побачу, що платіж відправлено».\n\n- **3.** «Можемо погодити більшу ставку?»\n\nЯкщо обрав 1, менеджер відповідає: «Холд стосується обробки, графік переказу окремий». Якщо обрав 2, він надсилає умови: мінімум $80, відправлення у п’ятницю після завершення холду й досягнення мінімуму. Якщо обрав 3, він повертає початкову ставку. У двох гілках без доказу повтори конкретний запит. У гілці 2 уяви, що доступно $72. Обери, чи показувати п’ятницю як дату гарантованого надходження або лишити дату відкритою до досягнення мінімуму.","exercises":[{"id":"BASE-01","types":["Оціни офер","Діалог"],"states":"[бриф Чехія плюс Meta Ads, три картки A B C, репліки 1–3, відповідь на обрану репліку, сценарій доступно 72]","input":"[choice A B C, choice причини A і C, text вісім полів B, choice репліка 1–3, choice рішення для залишку 72]","answer":"[B, для A лише пошук, для C немає реєстру викупу або визначених строків, репліка 2, дата відкрита до мінімуму]","decision":"B","evidence":"письмове джерело і реєстр B та конкретні причини відмови","nextStep":"запросити мінімум або графік переказу","wrongAnswer":"C через більшу ставку. Статус викупу й календар виплати неможливо перевірити."}]},"1.2":{"prompt":"**BASE-02 · Порахуй + Знаменник.** Вигаданий офер настільних ламп у Румунії. Покупець платить $39 (179,40 RON, покупець платить у леях). Баєру нараховують $15 за оплачений викуп. Із 100 зіставних кліків є 20 прийнятих заявок, 10 підтверджень і 6 зарахованих викупів. Реклама коштує $55. Сервіс списав 92 RON. Для вправи застосуй умовний курс 4,60 RON за долар. Партнер утримує 5% від нарахування під час виплати. Додаткових витрат немає. Рекламу й сервіс сплачено до нарахування. Статуси закриті, гроші можна використати після виплати.\n\nЗапиши частки апруву та викупу з їхніми базами. Відтвори перерахунок сервісу. Далі порахуй чисте нарахування, фактичний і граничний рекламний CPL, чистий EPC, результат, ROI й касову потребу. Порівняй точні значення до округлення. У відповіді округли гроші до цента, ROI — до сотих відсотка. Половину цента округлюй вгору. Визнач, чи фактичний CPL вкладається в межу.","exercises":[{"id":"BASE-02","types":["Порахуй","Знаменник"],"states":"[картка офера, зрілий звіт, спенд, сервіс у місцевій валюті, курс, комісія]","input":"- drag: чисельник і знаменник часток апруву й викупу. - number: сервіс, чисте нарахування, фактичний і граничний рекламний CPL, чистий EPC, результат, ROI та касова потреба. Допуск після округлення 0,01. - choice: фактичний CPL нижче, рівний або вище межі.","answer":"[10/20, 6/10, 20, 85.50, 2.75, 3.28, 0.86, 10.50, 14.00, 75, нижче]","decision":"фактичний CPL нижче межі","evidence":"правильні бази й облік комісії","nextStep":"відкласти фінансування з виплати до надходження","wrongAnswer":"10 × 15; оплачуються 6 викупів, а не 10 підтверджень."}]},"1.3":{"prompt":"**BASE-03 · Воронка + Діагноз.** Вигаданий офер органайзерів для авто. За тим самим періодом журнал сайту показує 150 відвідувань преленду та 90 натискань його кнопки. Є 45 завантажень лендингу. Реєстр партнера містить 15 прийнятих заявок і 6 зарахованих підтверджень. У звіті доставки є 4 викупи. Під час мобільного контролю кнопка натискається, але замість лендингу відкривається сторінка помилки.\n\nРозстав шість кроків. Підпиши джерела для завантаження лендингу, прийнятої заявки й викупу. Обчисли частку завантажень від натискань кнопки. Назви перший перехід для ремонту, відповідального й ознаку успішного повтору.","exercises":[{"id":"BASE-03","types":["Воронка","Діагноз"],"states":"[звіти за одним періодом, мобільний контроль із помилкою після кнопки]","input":"- sort: преленд, кнопка, лендинг, прийнята заявка, зарахування, викуп. - pairs: лендинг / заявка / викуп із трьома джерелами. - number: частка у відсотках; допуск 0. - choice: кнопка до лендингу / лендинг до заявки / підтвердження до викупу. - text: відповідальний і критерій повтору.","answer":"[преленд, кнопка, лендинг, прийнята заявка, зарахування, викуп, звіт сайту, реєстр партнера, звіт доставки, 50, кнопка до лендингу]","decision":"вибрано перехід із контрольним збоєм","evidence":"частка 45/90 і сторінка помилки","nextStep":"виправити адресу та повторити мобільний прохід із записом","wrongAnswer":"змінити креатив. Контроль зафіксував помилку після кнопки преленду."}]},"1.4":{"prompt":"**BASE-04 · Модератор.** Навчальний офер: підставка під ноутбук. Для кожного запису зроби свайп «пропустити» або «відхилити» і вибери причину: підтверджений опис, перебільшення, підміна сторінки, хибна комплектація. Пропуск означає, що матеріал пройшов саме ці перевірки в навчальній вправі.\n\n| Картка | Що бачить учень |\n|---|---|\n| A | Виміряна висота показана рулеткою. Сторінка містить ті самі розміри. |\n| B | «Підходить до кожного ноутбука». Є заміри лише для двох моделей. |\n| C | «Підходить до цих двох моделей». Є демонстрація і таблиця сумісності. |\n| D | Кнопка обіцяє підставку, але відкриває форму платної підписки. |\n\nДля двох сусідніх за змістом карток назви слово або умову, через яку змінюється рішення. Орієнтир для курсу — перевірка на оманливий опис та узгодженість кінцевої сторінки. З 9 вересня 2026 року Meta звела правила про шахрайство й оманливі комерційні практики в один стандарт — Prohibited Commercial Practices. Він діє і для звичайних публікацій, і для реклами та охоплює, зокрема, оманливі ціни, несанкціоновані рекомендації й гарантовану дохідність. [Meta · Prohibited Commercial Practices](https://transparency.meta.com/policies/community-standards/prohibited-commercial-practices/) · [Meta · Оновлення правила, 09.09.2026](https://transparency.meta.com/policies/other-policies/our-prohibited-commercial-practices-policy/)","exercises":[{"id":"BASE-04","types":["Модератор"],"states":"[чотири окремі картки A–D, для кожної опис і перелік причин]","input":"[swipe: пропустити або відхилити, choice: причина для кожної картки, text: умова що змінює рішення]","answer":"[A: пропустити, B: відхилити, C: пропустити, D: відхилити]","decision":"чотири правильні свайпи","evidence":"причина з опису матеріалу чи сторінки","nextStep":"конкретна правка хибного твердження","wrongAnswer":"Пропустити всі картки, бо вони стосуються одного товару."}]},"1.5":{"prompt":"**BASE-05 · Пари.** Вигаданий офер органайзера для багажника. Картка підтверджує зовнішні габарити, складання, перелік деталей, внутрішні відділення, інструкцію з очищення та оплату при отриманні.\n\nЗістав ситуації з доказами: 1 — мало місця; 2 — треба прибирати органайзер, коли він порожній; 3 — покупець порівнює набори; 4 — дрібні речі перемішуються; 5 — покупець питає про очищення; 6 — хоче знати, коли платити. Докази: А — власне розпакування; Б — замір; В — умови оплати; Г — демонстрація очищення за інструкцією; Д — неперервне складання; Е — розкладка речей по відділеннях.\n\nУ кожному рядку напиши кут і коротко опиши, що має бути в кадрі або на сторінці. Обери два кути для першого порівняння та підпиши, що залишиш сталим.","exercises":[{"id":"BASE-05","types":["Пари"],"states":"[картка органайзера, шість ситуацій, шість доказів]","input":"[pairs 1–6 з А–Е, text шість кутів, choice два кути, text незмінні умови]","answer":"[1-Б, 2-Д, 3-А, 4-Е, 5-Г, 6-В]","decision":"шість різних запитань","evidence":"усі пари й перевірні обіцянки","nextStep":"два кути з однаковими умовами показу та офером","wrongAnswer":"1-А. Розпакування показує вміст комплекту; сумісність потребує заміру."}]},"1.10":{"prompt":"**BASE-19 · Модератор.** Усі картки стосуються вигаданої підставки з оплатою при отриманні. Для кожної зроби свайп «пропустити» або «відхилити» і вибери причину. Під «пропустити» маємо на увазі, що картка пройшла саме перевірку цього кейсу.\n\n| Картка | Що бачить учень |\n|---|---|\n| A | «Знижка 50% сьогодні». Продавець не надав попередньої ціни або строку. |\n| B | «Ціна $30». На локальній сторінці та в картці офера зазначено той самий еквівалент. Спосіб оплати видно. |\n| C | Преленд показує вигаданий текст як справжній відгук покупця. |\n| D | Реклама обіцяє оплату при отриманні. Кнопка каже «Замовити з післяплатою», а форма відкриває ту саму пропозицію. |\n| E | Той самий шлях, але кнопка каже «Оплатити зараз», хоча передоплати немає. |\n\nПорівняй D та E і назви умову, через яку рішення змінюється. Перевіряємо достовірність умов, походження відгуку та узгодженість сторінки. З 9 вересня 2026 року Meta звела правила про шахрайство й оманливі комерційні практики в один стандарт — Prohibited Commercial Practices. Він діє і для звичайних публікацій, і для реклами та охоплює, зокрема, оманливі ціни, несанкціоновані рекомендації й гарантовану дохідність. [Meta · Prohibited Commercial Practices](https://transparency.meta.com/policies/community-standards/prohibited-commercial-practices/) · [Meta · Оновлення правила, 09.09.2026](https://transparency.meta.com/policies/other-policies/our-prohibited-commercial-practices-policy/)\n\nНе намагайся пройти перевірку в обхід. Правило Circumventing Systems забороняє ховати від перевірки зміст оголошення або кінцеву сторінку: клоакінг, символи Unicode для маскування слів, навмисно затемнені зображення. За систематичні порушення Meta може обмежити акаунт рекламодавця. [Meta · Circumventing Systems](https://transparency.meta.com/policies/ad-standards/deceptive-content/circumventing-systems)","exercises":[{"id":"BASE-19","types":["Модератор"],"states":"[п’ять окремих карток, для кожної опис і перелік причин]","input":"[swipe: пропустити або відхилити, choice: причина кожного рішення, text: відмінність D та E]","answer":"[A відхилити, B пропустити, C відхилити, D пропустити, E відхилити]","decision":"п’ять правильних свайпів","evidence":"знижка без підтвердження та вигаданий відгук і суперечність щодо оплати","nextStep":"виправити кожне місце і повторити перегляд","wrongAnswer":"Пропустити E, бо сам лендинг відкривається. Кнопка суперечить способу оплати."}]},"1.11":{"prompt":"**BASE-20 · Знайди блокер.** Для офера підставок команда має п’ять рядків передзапускового контролю. Торкнися першого рядка, який блокує запуск. На другому екрані його правку вже підтверджено. Торкнися блокера, який залишився. На папері обведи по одному номеру на кожному етапі.\n\n| Рядок | Етап | Факт |\n|---|---|---|\n| 1 | Адреса | Відкрився потрібний товар |\n| 2 | Негативний тест | Порожня форма показує підказку, запису немає |\n| 3 | Приймання | Повна форма створила заявку з click ID QA-219 |\n| 4 | Обробка | Партнер не оброблятиме заявки в запланований час |\n| 5 | Постбек | Статус тесту записано на попередній click ID QA-218 |\n\nДля другого екрана заміни факт у рядку 4 на «Партнер письмово підтвердив новий час, оператор доступний». Для обох блокерів назви відповідального і доказ повтору.","exercises":[{"id":"BASE-20","types":["Знайди блокер"],"states":"[п’ять інтерактивних рядків, новий факт у рядку 4 після першої відповіді]","input":"[tap_row: 1–5 на першому екрані, tap_row: 1–5 на другому екрані, text: власники й докази повтору]","answer":"[4, 5, партнер підтверджує час і власник інтеграції повторює з новим click ID]","decision":"два послідовні вибори","evidence":"графік і різні ID","nextStep":"підтвердження обробки і тест із прив’язкою статусу","wrongAnswer":"Торкнутися рядка 3. Приймання пройшло, відкриті збої стоять далі."}]},"1.12":{"prompt":"**BASE-21 · Порахуй + День за днем.** Для вигаданого офера полиць є $180 реклами на два варіанти, порівну. Зафіксовано межу рекламного CPL $10 і правило паузи після трьох таких меж без прийнятої заявки. На першому зрізі A витратив $30 і має нуль прийнятих; B має 6 прийнятих, статуси відкриті. Після обробки доступно лише 20 зрілих заявок на групу в окремому наступному прогоні. Запиши бюджет кожної групи, поріг, рішення по A і межу висновку про апрув 30% проти 40%. Для повтору спроєктуй власний план: одна змінна, одна фінальна метрика зі знаменником, умова паузи і момент фінального зрізу.","exercises":[{"id":"BASE-21","types":["Порахуй","День за днем"],"states":"[план 180, межа CPL 10, перший зріз, зрілий наступний прогін 20 на групу]","input":"[number: бюджет і поріг, choice: рішення по A, text: межа висновку, text: змінна, метрика зі знаменником, правило паузи і момент фінального зрізу]","answer":"[90, 30, пауза A, вибірки не вистачає для наведеної моделі]","decision":"пауза","evidence":"30 і нуль заявок","nextStep":"перевір маршрут і дочекайся статусів, plan: одна змінна та метрика зі знаменником плюс умова паузи і зрілий зріз","wrongAnswer":"A статистично програв. Спрацювало правило витрат."}]},"1.13":{"prompt":"**BASE-22 · Діагноз + Порахуй.** Три навчальні зрізи різних оферів: A — 100 кліків і 50 завантажень, на телефоні контроль дає помилку адреси. B — 16 надсилань, 14 прийнято, журнал позначив один тест і один повтор. C — 20 прийнятих, 3 зараховано, 7 відмов, 10 відкрито. Назви першу перевірку для A і поясни розбіжність B. Для A порахуй частку завантажень від кліків. Для C порахуй частку серед закритих і можливий діапазон зрілого апруву. Припустімо, відкриті заявки можуть і підтвердитися, і бути відхиленими.","exercises":[{"id":"BASE-22","types":["Діагноз","Порахуй"],"states":"[три незалежні звіти A B C]","input":"[choice перша перевірка A, text два записи B, number частка завантажень A, number частка серед закритих, number нижня і верхня межі C]","answer":"[адреса і мобільне завантаження, тест і повтор, 50%, 30%, 15%, 65%]","decision":"перевірки за сходинкою","evidence":"тест журнал і бази","nextStep":"дочекатися зрілості C","wrongAnswer":"30% є зрілим апрувом. Десять із двадцяти ще відкриті."}]},"1.14":{"prompt":"**BASE-23 · Порахуй + Діагноз.** Вигаданий офер органайзерів. Добова капа 12, уже зараховано 10, ще 2 заявки можуть підтвердитися цієї доби. Для окремої пропозиції збільшення рекламного бюджету з $60 до $75 матеріали за $10 сплачують до виплати. Доступно $78. Дві зрілі когорти позитивні. Назви номінальний залишок капи, найменший залишок після обробки відкритих заявок і потребу в коштах для збільшеного прогону. Запиши рішення щодо запуску та умови перегляду.","exercises":[{"id":"BASE-23","types":["Порахуй","Діагноз"],"states":"[капа 12, зараховано 10, відкрито 2, бюджет 75 плюс матеріали 10, каса 78]","input":"[number: два залишки і касова потреба, choice: рішення, text: умови перегляду]","answer":"[2, 0, 85, відкласти збільшення]","decision":"відкласти","evidence":"касовий дефіцит 7 і можливий нуль капи","nextStep":"підтвердити капу та покриття витрат до виплати","wrongAnswer":"збільшити через позитивні когорти; вони не покривають обмеження капи й живих грошей."}]},"final1":{"prompt":"**BASE-24 · Оціни офер + Журнал + Порахуй.** Виконай попередні кроки самостійно. Лише після рішення за першим журналом відкрий повтор. У ньому платність курсу вказано правильно. Порожня форма не створює Lead. Повна форма дала один запис із тим самим новим ID у трекері й партнера. Тестовий статус повернувся за цим ID, а повтор не подвоїв його. Інші передзапускові перевірки за умовами паперового прогону закрито.\n\nПісля умовного тесту спенд $90. Є 120 зіставних кліків, 22 Lead у Meta й 20 прийнятих заявок після відсіву тесту та повтору. На ранньому зрізі є 2 зарахування, 8 відмов і 10 відкритих. Після обробки всі статуси закриті: 4 зарахування й 16 відмов. У 9 відмовах згадано незручний розклад.\n\nПорахуй фактичний рекламний CPL за прийнятими, зрілу частку, нарахування, результат, EPC і ROI. Порівняй фактичний CPL з плановою та зрілою межами. Поясни, що відомо на ранньому зрізі. Вибери одну дію: стоп, оптимізація або масштабування. Для оптимізації запиши одну зміну, метрику та умову повторного рішення.\n\n### Здай коротке досьє тесту\n\nПеред тим як відкривати ключ, зроби окремий рядок для кожного рішення. У першому напиши, чи є письмовий дозвіл джерела, і назви запис, де видно оплачувану дію. У другому запиши планову межу й підпиши знаменник. У третьому намалюй три рівні чернетки. Для групи запиши сайт, GEO і перевірений сигнал. Для оголошення впиши два перші кадри й спільний матеріал. Окремо познач, що фактична рівність доставки не випливає з наявності двох роликів.\n\nДодай до досьє журнал із колонками «очікую / факт / власник / повтор». Для кнопки й сторінки назви обіцянку, яку бачить покупець. Для порожньої форми запиши, що має бути відсутнім. Для повної — який ID ти шукаєш у двох системах. У повторі порівняй очікування з тим, що сказано в новому журналі. Якщо повтор закрив технічний дефект, а текст усе ще суперечить брифу, запис лишається відкритим. Завершуй кожен рядок окремим доказом.\n\nПеред висновком перевір, чи підсумковий рядок можна повторити з трьох джерел. Для спенду збережи період рекламного звіту, для 20 прийнятих заявок — зрілий список без тестів і дублів, для чотирьох зарахувань — фінальний статус партнера. У рішенні окремо запиши, що виправити до нового тесту і яку змінну цього разу змінюєш. Якщо причина в розкладі курсу, передай продавцю частоту конкретної причини серед відмов і признач перевірку нового розкладу. Межа CPL після дозрівання відрізняється від планової — поясни цю різницю в одному реченні.\n\n### Підпиши фінансовий висновок\n\nПоділи аркуш на план, ранній зріз і зрілий звіт. У плані підпиши припущення щодо частки. На ранньому зрізі познач відкриті статуси. У зрілому звіті запиши фактичну базу й розрахунки. Окремо зазнач дати витрат, зарахування та доступу до грошей. Заверши одним реченням про дію та одним про доказ, якого потребуватиме повтор. Якщо пропонуєш змінити розклад у креативі, використай лише той розклад, який школа підтвердила. Відмова через графік є підставою для гіпотези, а не підтвердженням причини збитку.","exercises":[{"id":"BASE-24","types":["Оціни офер","Журнал","Порахуй"],"states":"[три картки, перший журнал, повтор після рішення, ранній зріз, зрілий зріз]","input":"[choice: офер і причини, number: планова межа і каса, text: чернетка та карта, journal: три дефекти і повтор, number: CPL, апрув, нарахування, результат, EPC, ROI та зріла межа, choice: дія, text: обґрунтування]","answer":"[B, 5, 110, три блокери, 4.50, 20%, 96, -14, 0.80, -12.73%, 3.80, стоп поточного варіанта або окремий обґрунтований оптимізаційний тест]","decision":"доказовий вибір офера і без масштабу","evidence":"журнал і правильні знаменники","nextStep":"окрема перевірка гіпотези розкладу або завершення тесту","wrongAnswer":"масштабувати через CPL нижче планової межі. За зрілою часткою тест збитковий."}]},"1.6a":{"prompt":"**BASE-06 · Пари.** Вигаданий товар — складаний органайзер для багажника. Картка підтверджує складання, на сторінці видно габарити й оплату при отриманні. Покупець питає, як прибрати органайзер, коли ним не користується. Зістав поля «перший кадр A», «перший кадр B», «спільний доказ» і «CTA» з фрагментами:\n\n- **К1.** Показати, як великий порожній органайзер займає місце в багажнику.\n\n- **К2.** Показати цей самий органайзер у складеному вигляді.\n\n- **К3.** Зняти, як той самий виріб складається, одним неперервним кадром.\n\n- **К4.** «Відкрий сторінку й звір габарити».\n\n- **К5.** «Замов сьогодні зі знижкою». У картці знижки немає.\n\nЗа задумом A починається з проблеми, B — з результату. Додай у бриф однаковий напис для A і B, спільну обіцянку й список того, що залишиться сталим. Запиши причину, з якої відкинеш К5.","exercises":[{"id":"BASE-06","types":["Пари"],"states":"[картка органайзера, запитання про зберігання, п’ять фрагментів, порядок A проблема B результат]","input":"[pairs: A B доказ CTA з К1–К5, text: спільні обіцянка й напис, text: незмінні умови й причина відмови від К5]","answer":"[A-К1, B-К2, доказ-К3, CTA-К4]","decision":"кут про складання і правильні пари","evidence":"демонстрація реального складання","nextStep":"передати два перші кадри та однакову спільну частину","wrongAnswer":"К5 як CTA; картка не підтверджує знижку."}]},"1.6b":{"prompt":"**BASE-07 · Пари + Воронка.** Товар — складана підставка для планшета. Картка підтверджує складання та комплект із чохлом. Покупець питає, як прибрати підставку після роботи. Маєш фрагменти: A — розкладена підставка займає місце; B — складена підставка на тому самому столі; C — неперервне складання; D — підставка й чохол як комплект; E — «Відкрий сторінку й подивись комплект». Ціну в брифі не дали.\n\nРозстав блоки для 12 секунд: 0–2, 2–7, 7–9, 9–12. У стартовий блок впиши два варіанти. Для решти признач спільні кадри й написи. Перевір, щоб жоден напис не обіцяв нижчу ціну чи швидкість складання, яких бриф не містить.","exercises":[{"id":"BASE-07","types":["Пари","Воронка"],"states":"[п'ять фрагментів, чотири часові інтервали, вертикальна рамка 9:16]","input":"[pairs A і B з початком, sort C D E після початку, text напис для кожного блоку]","answer":"[0–2 A/B, 2–7 C, 7–9 D, 9–12 E]","decision":"два рівні за часом початки","evidence":"спільний доказ і підтверджений комплект","nextStep":"передати сценарій із точкою склейки на 2-й секунді","wrongAnswer":"D замість C як доказ складання; комплект не показує, як виріб складається."}]},"1.6c":{"prompt":"**BASE-08 · Журнал.** Товар — складана підставка для планшета. У сценарії A і B різняться тільки відеорядом 0–2 с, спільні блоки стоять на 2–7, 7–9 і 9–12 с. Перший напис, звук і CTA мають збігатися. Картка підтверджує складання й чохол у комплекті.\n\n| Контроль | Факт в A | Факт у B |\n|---|---|---|\n| Початковий відеокадр | Підставка розкладена, 0–2 с | Підставка складена, 0–3 с |\n| Спільний доказ | Складання, 2–7 с | Складання, 3–7 с |\n| Комплект | Чохол у комплекті, 7–9 с | Чохол у комплекті, 7–9 с |\n| CTA | «Подивись комплект», 9–12 с | «Подивись комплект», 9–12 с |\n| Напис, звук і рамка | За сценарієм | За сценарієм |\n\nЗаповни для B «очікую / факт / рішення» для початку й доказу. Назви одну монтажну правку, яка відновить спільну частину, і дві часові позначки, які звіриш у новому експорті.","exercises":[{"id":"BASE-08","types":["Журнал"],"states":"[сценарій 12 с, журнал експортів A і B]","input":"[journal: очікування факт рішення для двох рядків, text: правка і дві часові позначки]","answer":"[B початок 0–2 с замість 0–3 с, B доказ 2–7 с замість 3–7 с, звірити 2 і 7 с]","decision":"B повертаємо на монтаж","evidence":"помилка у двох інтервалах","nextStep":"відновити спільний фрагмент та перевірити його межі в експорті","wrongAnswer":"прийняти B за загальними 12 секундами. Доказ у B коротший."}]},"1.6d":{"prompt":"**BASE-09 · Модератор.** Навчальний офер: складана підставка для планшета. Для кожного запису зроби свайп «пропустити» або «відхилити» і вибери причину: підтверджений опис, перебільшення, підміна сторінки, хибна комплектація. Пропуск означає, що матеріал пройшов саме ці перевірки в навчальній вправі.\n\n| Картка | Що бачить учень |\n|---|---|\n| A | Показано модель із картки, текст у межах кадру, кнопка відкриває саме цю модель. |\n| B | Актор демонструє дорожчу модель, кнопка веде на базову без цієї функції. |\n| C | На кадрі «чохол у комплекті». Фактично чохол можна придбати окремо. |\n| D | На кадрі «чохол окремо». Умову видно в перегляді й повторено на сторінці. |\n\nДля двох сусідніх за змістом карток назви слово або умову, через яку змінюється рішення. Орієнтир для курсу — перевірка на оманливий опис та узгодженість кінцевої сторінки. З 9 вересня 2026 року Meta звела правила про шахрайство й оманливі комерційні практики в один стандарт — Prohibited Commercial Practices. Він діє і для звичайних публікацій, і для реклами та охоплює, зокрема, оманливі ціни, несанкціоновані рекомендації й гарантовану дохідність. [Meta · Prohibited Commercial Practices](https://transparency.meta.com/policies/community-standards/prohibited-commercial-practices/) · [Meta · Оновлення правила, 09.09.2026](https://transparency.meta.com/policies/other-policies/our-prohibited-commercial-practices-policy/)","exercises":[{"id":"BASE-09","types":["Модератор"],"states":"[чотири окремі картки A–D, для кожної опис і перелік причин]","input":"[swipe: пропустити або відхилити, choice: причина для кожної картки, text: умова що змінює рішення]","answer":"[A: пропустити, B: відхилити, C: відхилити, D: пропустити]","decision":"чотири правильні свайпи","evidence":"причина з опису матеріалу чи сторінки","nextStep":"конкретна правка хибного твердження","wrongAnswer":"Пропустити всі картки, бо вони стосуються одного товару."}]},"1.7a":{"prompt":"**BASE-10 · Воронка.** Вигаданий офер органайзера для багажника. Оголошення обіцяє допомогти звірити ширину багажника. Продавець підтвердив, що на сторінці органайзера є його габарити й оплата при отриманні. Маєш п’ять блоків: A — інструкція заміру; B — «Відкрий габарити органайзера»; C — фото заміру з двома позначеними краями; D — заголовок «Звір ширину багажника»; E — умови оплати й пояснення, що відкриється сторінка товару.\n\nРозташуй блоки за шаблоном уроку. Перенеси їх у власну чернетку й напиши під заголовком інструкцію з вимірювання ширини багажника. Познач, які точки має підтвердити фото. Уточни, до якого блока лендингу веде кнопка. Напиши, що зробиш, якщо на тестовій сторінці габаритів немає.","exercises":[{"id":"BASE-10","types":["Воронка"],"states":"[бриф органайзера, п’ять блоків A–E, сторінка за кнопкою]","input":"[sort: A–E, choice: блок габаритів / форма / інший товар, text: коротка інструкція, точки у фото й рішення за відсутності габаритів]","answer":"[D A C E B, блок габаритів]","decision":"правильна послідовність","evidence":"фото підтверджує спосіб заміру","nextStep":"відкласти передачу в публікацію до перевірки параметрів і повторити перехід","wrongAnswer":"B перед доказом у цьому шаблоні. Покупець ще не отримав обіцяну інструкцію."}]},"1.7b":{"prompt":"**BASE-11 · Журнал.** Офер — складаний органайзер для багажника. Преленд веде до габаритів. Продавець підтвердив габарити, чохол у комплекті та оплату при отриманні. Під час контролю ти бачиш:\n\n| Контроль | Факт |\n|---|---|\n| Призначення кнопки преленду | Відкриває модель із габаритами |\n| Комплект | Видно органайзер із чохлом |\n| CTA | «Оплатити зараз» |\n| Порожній контакт | Відображається «Заявку отримано» |\n\nСклади коротку чернетку п’яти блоків. Для двох проблем заповни «очікую / факт / рішення». Напиши текст кнопки й повідомлення для успіху та помилки. Назви відповідального за повтор.","exercises":[{"id":"BASE-11","types":["Журнал"],"states":"[картка органайзера, чернетка переходу, чотири факти]","input":"[text: п’ять блоків, journal: два ряди, text: кнопка й два стани, text: власник повтору]","answer":"[CTA: заявка з післяплатою, порожній контакт: помилка без підтвердження]","decision":"два дефекти","evidence":"умови картки й факти форми","nextStep":"правка та повтор успішної й порожньої відправки","wrongAnswer":"прийняти форму, бо вона показує підтвердження. Порожній контакт не має потрапити у стан успіху."}]},"1.7c":{"prompt":"**BASE-12 · Знайди блокер.** Перевір тестову заявку на чохол для валізи. Торкнися першого рядка журналу, де ламається зв’язок із вихідним кліком. На папері обведи номер рядка. Після вибору вкажи, хто перевірить передачу і що має показати повторний тест.\n\n| Рядок | Крок | Факт |\n|---|---|---|\n| 1 | Тестове оголошення | Відкрило преленд, у журналі кліків QA-713 |\n| 2 | Кнопка преленду | Відкрила лендинг, той самий QA-713 отримано |\n| 3 | Форма | Обов’язкові поля пройшли перевірку, екран успіху відкрився |\n| 4 | Запис після форми | Партнер записав заявку L-27, поле click ID порожнє |\n| 5 | Фінальний звіт | Заявка L-27 є, прив’язки до контрольного кліка немає |","exercises":[{"id":"BASE-12","types":["Знайди блокер"],"states":"[журнал з п’ятьма інтерактивними рядками, картка очікуваного ID QA-713]","input":"[tap_row: 1–5, choice: власник форми або звіту або креативу, text: очікування повтору]","answer":"[4, власник форми та її інтеграції, нова контрольна заявка з тим самим ID що в журналі кліків]","decision":"рядок першої втрати ID","evidence":"останній запис QA-713 на лендингу й порожнє поле заявки","nextStep":"контроль від оголошення до звіту","wrongAnswer":"Рядок 5 лише показує наслідок. Порожнє поле видно раніше."}]},"1.8a":{"prompt":"**BASE-13 · Журнал.** У навчальному офері підставки трекер створив ID CLICK-T. На преленді видно CLICK-T. Журнал приймання форми теж показує CLICK-T. Партнерський реєстр містить номер заявки LEAD-T і порожнє поле кліка. Намалюй маршрут із чотирьох етапів і підпиши, хто створює обидва ID. Заповни чотири рядки «очікую / факт / рішення». Познач останній підтверджений перехід, кому передаси проблему і що має показати повтор.","exercises":[{"id":"BASE-13","types":["Журнал"],"states":"[журнали трекера, преленду, форми й партнера; CLICK-T і LEAD-T]","input":"[text: карта і два джерела ID, journal: чотири рядки, choice: останній підтверджений етап, text: відповідальні й результат повтору]","answer":"[трекер проходить, преленд проходить, форма проходить, реєстр на правку, останній доказ у журналі приймання форми]","decision":"перевірити передачу від приймання форми до реєстру","evidence":"карта з джерелами обох ID і CLICK-T у формі без значення у полі кліка партнера","nextStep":"звірити поля й повторити з новим тестовим ID","wrongAnswer":"LEAD-T є заміною CLICK-T. Це номер заявки, а поле кліка порожнє."}]},"1.8b":{"prompt":"**BASE-14 · Журнал.** Трекер має клік C-TEST, партнерська заявка L-TEST містить його в полі «Клік». Партнер документує макроси «КЛІК-П» і «СТАТУС-П». У журналі запиту видно буквальний текст «ІНШИЙ-КЛІК» у полі subid, а статус підтвердження розпізнається за картою. Запиши відповідність полів, очікування, факт і рішення. Назви результат повтору.","exercises":[{"id":"BASE-14","types":["Журнал"],"states":"[звіт кліка, рядок заявки, опис макросів, факт запиту]","input":"[journal: subid і status, text: правка та очікуваний результат]","answer":"[subid з КЛІК-П, status зі СТАТУС-П, ІНШИЙ-КЛІК не підставлено]","decision":"виправити джерело subid","evidence":"прямий ID у партнера і нерозкритий макрос","nextStep":"повтор із новим кліком і розпізнаним статусом","wrongAnswer":"підставити L-TEST у subid; номер заявки не є ID кліка."}]},"1.8c":{"prompt":"**BASE-15 · Діагноз.** Після успішної заявки журнал сторінки має один запис із ключем F-TEST. Pixel передав Lead із F-TEST, CAPI — Lead із SERVER-T. Порожня форма не створила бізнес-запису, але Pixel теж надіслав Lead. Заповни в журналі «очікую / факт / рішення» для обох тестів. Поясни, що змінити й що має показати повтор.\n\nУ відповіді вибери діагноз і першу перевірку: зіставити назву й ID обох повідомлень або рахувати кожне окремою заявкою. Назви, який результат повтору підтвердить виправлення.","exercises":[{"id":"BASE-15","types":["Діагноз"],"states":"[прийнята форма з двома подіями, порожня форма з хибним Lead]","input":"[choice: діагноз, choice: перша перевірка, text: контрольний доказ]","answer":"[для повної форми спільний ключ, для порожньої Lead відсутній]","decision":"два дефекти","evidence":"F-TEST проти SERVER-T та хибний Lead","nextStep":"узгодити ID і прив’язати подію до приймання","wrongAnswer":"однакової назви Lead досить. Для обраного методу потрібен також збіг ID."}]},"1.8d":{"prompt":"**BASE-16 · Журнал.** Вигаданий офер чохлів. Домовлено, що сигнал підтвердження створюється лише після остаточного зарахування. Ось контроль:\n\n| Тест | Факт |\n|---|---|\n| Позитивний | Партнер зарахував заявку A. У діагностиці є одна подія з очікуваним ключем |\n| Негативний | Заявка B ще очікує. Подія підтвердження вже є |\n| Повторний | Те саме зарахування A доставлено повторно й створено ще одну логічну подію під новим ключем |\n| Незбіг | У записі C номер не знаходиться в контрольному журналі. Події немає, запис на звірці |\n\nЗаповни «очікую / факт / рішення» для кожного рядка. Назви дві правки й результат повтору.","exercises":[{"id":"BASE-16","types":["Журнал"],"states":"[чотири тести A B повтор A C]","input":"[journal: чотири рядки, text: дві правки й повтор]","answer":"[позитивний проходить, негативний на правку, повторний на правку, незбіг правильно спрямовано на звірку]","decision":"знайдено два дефекти","evidence":"ранній статус і новий ключ повтору","nextStep":"обмежити тригер і зберегти стабільний ключ","wrongAnswer":"прийняти повтор як нову подію; це та сама підтверджена дія."}]},"1.9a":{"prompt":"**BASE-17 · Пари + Діагноз.** Офер підставок. Магазин володіє акаунтом, сторінкою і джерелом подій. Баєр відкриває сторінку, але акаунта не бачить. Аналітик бачить звіт і не може редагувати кампанії. Для іншого акаунта власник бачить повідомлення про обмеження. Заповни три рядки «очікую / факт / рішення». Назви власника наступної дії та ознаку повторної перевірки.\n\nЗістав потрібне право з власником і активом. Потім обери першу перевірку для відкритого права: повтор під власним профілем або вхід під адміністратором.","exercises":[{"id":"BASE-17","types":["Пари","Діагноз"],"states":"[карта активів і три факти]","input":"[pairs: права та активи з власниками, choice: перша контрольна дія, text: доказ повтору]","answer":"[видати потрібне право на акаунт, залишити аналітику читання, передати обмеження уповноваженому власнику]","decision":"три різні рішення","evidence":"відсутній акаунт проти наявного звіту й повідомлення про обмеження","nextStep":"офіційний доступ або перегляд","wrongAnswer":"дати всім повний контроль. Це не відповідає задачі аналітика й не знімає обмеження."}]},"1.9b":{"prompt":"**BASE-18 · Збери кампанію.** Офер підставок, країна Чехія. Є сайт, перевірена подія Lead після приймання форми, сторінка бренду, ролик і адреса лендингу. Команда хоче заявки й окремий бюджет однієї групи. Розклади ціль, рівень керування бюджетом, суму групи, GEO, сайт, набір даних, Lead, сторінку, ролик і адресу. Потім назви доказ перед публікацією.","exercises":[{"id":"BASE-18","types":["Збери кампанію"],"states":"[бриф, десять карток полів, три рівні]","input":"[sort: картки за рівнями, text: контроль події й маршруту]","answer":"[кампанія: ціль і спосіб бюджету, група: сума GEO сайт набір Lead, оголошення: сторінка ролик адреса]","decision":"три рівні","evidence":"правильний набір і адреса","nextStep":"перегляд та прийнята контрольна заявка","wrongAnswer":"Lead на рівні оголошення. У цьому сценарії його визначає група."}]},"2.1":{"prompt":"**INFRA-01 · Оціни офер.** Заплановано $80 рекламного бюджету. A: акаунт належить магазину, роль видає адміністратор, є звіт, платіжна рамка дозволяє витратити заплановані $80. B: агенція дає свій акаунт і роль, але не надає умов комісії та фінального звіту. C: продавець передає пароль до чужого акаунта й обіцяє обійти обмеження. Обери варіант для підготовки. Для B назви відкриті поля, для C поясни ризик. Запиши, що перевіриш перед першою витратою.","exercises":[{"id":"INFRA-01","types":["Оціни офер"],"states":"[бюджет 80, три сценарії A B C]","input":"[choice A B C, text причини для двох інших, text контроль до витрат]","answer":"[A, B відкрита комісія і звіт, C непрозора власність і обхід]","decision":"A на підготовку","evidence":"власність роль звіт і рамка","nextStep":"звірити чернетку та платіжну рамку до витрат","wrongAnswer":"C через обіцяний траст. Немає прозорого власника й офіційного доступу."}]},"2.2":{"prompt":"**INFRA-02 · Журнал.** Магазин ламп зберігає власність на акаунт, сторінку й набір подій. Агенція готує чернетку, аналітик читає звіт. Баєр агенції може відкрити акаунт і вибрати сторінку, але потрібного набору в групі не бачить. Аналітик відкриває звіт. Після завершення роботи лише доступ агенції потрібно відкликати. Заповни рядки для трьох активів і аналітика. Для кожного напиши «очікую / факт / рішення». Запиши порядок повтору й відкликання.","exercises":[{"id":"INFRA-02","types":["Журнал"],"states":"[магазин володіє трьома активами, задачі агенції й аналітика, звіт перевірки]","input":"[journal: чотири рядки, text: власник повтору й послідовність відкликання]","answer":"[акаунт проходить, сторінка проходить, набір даних потребує звірки права та прив’язки до акаунта, читання звіту проходить]","decision":"виправити лише відкритий доступ","evidence":"контроль під профілем виконавця","nextStep":"повторити вибір набору та відкликати доступ агенції після передачі","wrongAnswer":"замінити профіль баєра паролем адміністратора; це не перевіряє видані права."}]},"2.3":{"prompt":"**INFRA-03 · Діалог.** Баєр не бачить сторінку після зміни ролі. Обери, що написати адміністратору: **А.** «Дай пароль»; **Б.** «Покажи, чи цей профіль має право використовувати сторінку для чернетки»; **В.** «Подай апеляцію».\n\nПісля А адміністратор відмовляється передавати пароль. Після Б він підтверджує, що доступ до сторінки не видано. Після В показує, що рішення модерації щодо цієї сторінки немає. Обери наступну дію: попросити видати потрібне право й перевірити сторінку під власним профілем або звернутися зі скаргою на обмеження. Для іншого акаунта адміністратор бачить окреме повідомлення про обмеження. Назви поля, які попросиш зберегти перед вибором способу перегляду.","exercises":[{"id":"INFRA-03","types":["Діалог"],"states":"[пропала сторінка після зміни ролі, три репліки, гілка за обраною реплікою, окреме повідомлення іншого акаунта]","input":"[choice: репліка А–В, choice: наступна дія, text: поля повідомлення]","answer":"[Б, офіційно видати потрібне право і повторити під профілем баєра, об’єкт і причина та дата і доступність перегляду]","decision":"відновити право і розрізнити два випадки","evidence":"статус ролі або повідомлення","nextStep":"контроль власним профілем та окрема звірка рішення","wrongAnswer":"Подати апеляцію через відсутню сторінку. У кейсі проблема у виданих правах."}]},"2.4":{"prompt":"**INFRA-04 · Порахуй.** Вигаданий тест має бюджет $90. Спенд поточної кампанії $55. Рахунок на $70 включає ці $55 і $15 іншої кампанії. У банку проведено $70. Матеріали поточного тесту коштували $10 і сплачені окремо до виплати. Запиши спенд, суму рахунку та витрати поточного тесту до виплати. Назви, що перевіриш, якщо банк раптом покаже ще одне списання.\n\nВведи три суми в окремі поля: спенд кампанії, рахунок і витрати цього тесту. Для другого списання вибери першу перевірку: звірити ID і статус або додати його без звірки.","exercises":[{"id":"INFRA-04","types":["Порахуй"],"states":"[бюджет 90, спенд 55, рахунок 70, інша кампанія 15, матеріали 10]","input":"[number: спенд, number: рахунок, number: витрати тесту, choice: звірити ID і статус або додати без перевірки]","answer":"[55, 70, 65]","decision":"різниця належить іншій кампанії","evidence":"55 плюс 15 і 55 плюс 10","nextStep":"звірити стан й ID другого платежу","wrongAnswer":"Вписати 80 як витрати тесту, додавши весь рахунок до матеріалів."}]},"2.5":{"prompt":"**INFRA-05 · Діагноз.** У резерві офера підставок сторінка відкрилася, клік і форма мають T-R, а статус є тільки в партнерському журналі. Копія збережена до кількох нових заявок. Запиши два відкриті питання й докази, що їх закривають.\n\nОбери діагноз: збій до форми, збій повернення статусу або повністю відновлений маршрут. Далі обери перший контроль: повернення статусу за тим самим тестовим кліком або лише відкриття сторінки. Окремо назви первинне джерело для заявок після копії.","exercises":[{"id":"INFRA-05","types":["Діагноз"],"states":"[копія, контрольний клік T-R, партнерський статус, прогалина після копії]","input":"[choice: діагноз, choice: перший контроль, text: доказ для прогалини після копії]","answer":"[відновити повернення статусу, звірити прогалину за журналом партнера]","decision":"витрати на паузі","evidence":"останній підтверджений запис","nextStep":"тест і звірка періоду","wrongAnswer":"Повернути трафік після відкриття сторінки."}]},"2.6":{"prompt":"**INFRA-06 · Знайди блокер.** Торкнися першого рядка, який блокує маршрут із реклами. Після виправлення повтори всі рядки й назви власника відкритої перевірки. На папері обведи номер.\n\n| Рядок | Контроль | Факт |\n|---|---|---|\n| 1 | Прямий HTTPS | Потрібна сторінка відкривається |\n| 2 | Натискання з оголошення | Відкривається сторінка старої моделі |\n| 3 | Форма на потрібній сторінці | Створює контрольну заявку |\n| 4 | Платформна верифікація | В умовах тесту потрібна, підтвердження ще немає |","exercises":[{"id":"INFRA-06","types":["Знайди блокер"],"states":"[чотири інтерактивні рядки DNS і сторінки, після вибору уточнюється результат повтору]","input":"[tap_row: 1–4, text: власник правки та власник перевірки верифікації]","answer":"[2, власник рекламного маршруту і адміністратор домену або активу]","decision":"перша розбіжність у рядку 2","evidence":"прямий і рекламний переходи дають різні моделі","nextStep":"контроль всього маршруту і окрема верифікація","wrongAnswer":"Рядок 1 як доказ готовності. Він підтверджує лише прямий вхід."}]},"2.7":{"prompt":"**INFRA-07 · Пари.** Офер ламп. Є чотири передачі: рамка витрат, два файли з правами, тестовий ID з журналом і зрілий висновок. Зістав їх із тімлідом, креативником, технічним спеціалістом та баєром. Форма дала підтвердження, але реєстр порожній. Запиши власника правки і того, хто її прийме.\n\nПеретягни чотири передачі до ролей. Далі зістав два завдання — «виправляє форму» і «приймає повтор» — з технічним спеціалістом і баєром.","exercises":[{"id":"INFRA-07","types":["Пари"],"states":"[чотири ролі і чотири передачі, дефект форми]","input":"[pairs: чотири передачі й ролі, pairs: власник правки і приймання]","answer":"[тімлід бюджет, креативник матеріали, техспец тест, баєр висновок]","decision":"запуск чекає","evidence":"два журнали","nextStep":"техспец виправляє і баєр приймає","wrongAnswer":"Просити креативника виправити форму."}]},"2.8":{"prompt":"**INFRA-08 · Порахуй + Пари.** У вигаданому тесті партнер нарахував $150, утримав $6 й переказав $144. Реклама $95, матеріали $15, обидві суми сплачено до виплати. Порахуй чистий підсумок до податків і касову потребу. Назви документи та три дати, потрібні для консультації.\n\nВведи дві суми й зістав три дати з доказами: дату витрат із випискою чи первинним документом, дату нарахування зі звітом партнерки, дату надходження з платіжною випискою.","exercises":[{"id":"INFRA-08","types":["Порахуй","Пари"],"states":"[валові 150, комісія 6, переказ 144, витрати 95 і 15]","input":"[number: фінансовий результат, number: каса, pairs: три дати й документи]","answer":"[34, 110]","decision":"відокремити переказ від прибутку","evidence":"144 мінус 110","nextStep":"пакет фахівцю","wrongAnswer":"Записати 28, повторно віднявши комісію."}]},"2.9":{"prompt":"**INFRA-09 · Оціни офер + Діагноз.** Офер аксесуарів. A: власне відео й однакова ціна на маршруті. B: оголошення показує низьку разову ціну, а форма приховує підписку. C: звіти мають різний період, команда називає різницю шейвом. Запиши факт, шкоду й дію для кожного.\n\nВибери, яку картку можна передати на звичайну перевірку, а яку слід відкласти через приховану підписку. Для C обери діагноз і першу перевірку: різні зрізи потребують вирівнювання або шейв уже доведено.","exercises":[{"id":"INFRA-09","types":["Оціни офер","Діагноз"],"states":"[три незалежні картки A B C]","input":"[choice: картка для перевірки, choice: картка на паузу, choice: діагноз C та перший контроль]","answer":"[A первинна перевірка, B відкласти до прозорих умов, C вирівняти звіти й зіставити ID]","decision":"розрізнено ризики","evidence":"текст підписки й різні періоди","nextStep":"показати умови й звірити записи","wrongAnswer":"Вважати різницю звітів доказом шейву."}]},"2-final":{"prompt":"**INFRA-10 · Журнал + Порахуй.** Вигаданий офер застосунку. Реклама $90, підготовка $20, все до виплати. Баєр відкрив акаунт і сторінку, але не бачить потрібного джерела подій. Аналітик звіт читає. На резерві форма створила правильний ID, а повернення статусу немає. Платник бачить два записи з тією самою сумою: один завершений, один очікує. Допиши касову потребу, статус кожного рядка, власників і повтор. Поясни, чому другий запис ще не можна додати до завершених витрат.\n\n### Запиши, що саме здаєш\n\nПідготуй один журнал. На початку запиши назву тесту, країну, джерело, версію матеріалу й власника бюджету. Далі прочитай кожен рядок очима людини, яка приймає роботу. Якщо йдеться про акаунт, їй потрібен доказ під профілем виконавця. Якщо про резерв, потрібний тестовий запис, який пройшов до останньої системи. Якщо про оплату, у рядку має бути період, сума і стан. Формулювання «все готово» не дозволить відтворити рішення.\n\n| Ділянка | Очікування до перегляду фактів | Який доказ збережеш |\n|---|---|---|\n| Власність | Підготовку ведуть у потрібному акаунті | Власник, робоча роль і дія під профілем виконавця |\n| Рекламна чернетка | Правильні сторінка й джерело подій | Перелік доступних у чернетці активів і назва обраного набору |\n| Кошторис | Реклама й матеріали можна оплатити до виплати | Дві статті витрат і підтверджене джерело грошей |\n| Резерв | Форма й статус мають той самий тестовий ID | Трекер, реєстр партнера та журнал повернення |\n| Платіж | Лише завершений запис входить до завершених операцій | Фактичний стан та ID платежу |\n\nПеред відкриттям журналу підпиши, яку подію можна прийняти як факт. У рядку джерела подій достатньо побачити, що правильний набір доступний у чернетці. Це ще не доводить саму подію. Якщо її теж перевіряєш, потрібний окремий контрольний запис. Так само наявність заявки в партнерському реєстрі не дозволяє прийняти повернення статусу в трекері. У фіналі збережи ці межі доказу.\n\n### Пройди повтор після рішення\n\nЛише після того, як назвав відкриті питання, прочитай другий зріз. Адміністратор звірив роль і прив’язку правильного набору до акаунта. Під своїм профілем баєр відкриває чернетку й вибирає цей набір. У відповідальному тестовому середовищі резерв створив новий ключ. Партнер прийняв його у формі, а трекер отримав за ним тестовий статус. Платник відкрив історію операцій і підтвердив, що другий платіж скасовано. Джерело грошей на $110 підтверджено. За паперовим брифом інші передзапускові перевірки вже закриті.\n\nПорівняй повтор із попереднім зрізом. Для набору подій потрібен доказ під профілем баєра, тож перегляд адміністратора сам по собі був би недостатній. Для резерву потрібен той самий новий ключ у всіх записах, тож один рядок форми не закрив би статус. Для другого платежу потрібний кінцевий стан, тож відсутність повторного повідомлення від банку не була б доказом скасування. Запиши, які три рядки тепер можна закрити й на чому ґрунтується кожне рішення.\n\nПеред тим як схвалити паперову чернетку, коротко перекажи результат: набір обирається під профілем баєра, партнерський статус повертається за тим самим новим ключем, другий платіж скасовано. Далі підпиши, хто прийняв кожний крок. Якщо у звіті лише загальне «все працює», поверни запис власнику й попроси вказати доказ. Статус у фіналі стосується тільки тих версій, які пройшли\n\nповтор.\n\n### Зафіксуй межу фіналу\n\nПаперовий контроль показує, що надані докази узгоджуються. Реальний проєкт вимагав би пройти ті самі дії у своєму середовищі. У журналі постав дату, підпиши, хто прийняв повтор, і залиш першу спробу поруч. До фінансового журналу додай назви обох платіжних записів. До фінансової частини додай дату, коли сплатили рекламу, коли мережа зарахувала дію, коли гроші стали доступними. У цій вправі каса покривається до виплати. Приймати рішення за вже нарахованими, але не отриманими грошима не потрібно. Якщо команда перевіряє новий офер, повтори весь контроль, а зі старого журналу бери тільки структуру та визначення.","exercises":[{"id":"INFRA-10","types":["Журнал","Порахуй"],"states":"[активи, кошторис, резерв, два статуси платежу]","input":"[number: каса, journal: доступ, резерв, платежі, text: рішення до й після повтору]","answer":"[110, звірка джерела, резерв потребує постбеку, очікуваний платіж на звірці, після повтору три блокери закрито в межах паперових даних]","decision":"відкласти витрати","evidence":"два відкриті технічні рядки та один фінансовий","nextStep":"повтор під профілем баєра і тест статусу","wrongAnswer":"Вважати два рядки однакової суми двома завершеними витратами."}]},"3.1.1":{"prompt":"**TOV-01 · Оціни офер.** Підготуй один тест Meta у Польщі. A — органайзер $38 (≈152 PLN, покупець платить у злотих), ставка $11 за зараховане підтвердження, письмово дозволено Meta, польська форма та доставка підтверджені. B — підставка $43, ставка $15 за викуп, зони доставки ще невідомі. C — дорожній чохол $30, ставка $9 за підтвердження, дозволено лише пошук. Вибери картку, назви причини паузи інших і один доказ до витрат.","exercises":[{"id":"TOV-01","types":["Оціни офер"],"states":"[бриф Meta у Польщі, три незалежні картки]","input":"[choice: офер, text: дві причини паузи і доказ до витрат]","answer":"[A, B немає покриття, C дозволено пошук]","decision":"A до підготовки","evidence":"польська форма та покриття і письмовий канал","nextStep":"контрольний прохід і звірка допуску","wrongAnswer":"B через ставку. Доставка не підтверджена."}]},"3.1.2":{"prompt":"**TOV-02 · Порахуй.** У вигаданого офера поличок у США ціна $45, ставка $12 за зарахований викуп. Є 40 прийнятих заявок, 20 підтверджень, 12 зарахованих викупів, $101 реклами і $25 супутніх витрат. Усе сплачено до переказу. Порахуй апрув, частку викупу, наскрізну частку, результат, межу рекламного CPL і касову потребу. Що зміниться, якщо два викупи сторнують?","exercises":[{"id":"TOV-02","types":["Порахуй"],"states":"[ціна 45, ставка 12 за викуп, зрілі статуси, витрати 101 і 25, наступне сторнування двох дій]","input":"[number: три частки, number: результат і межа CPL і каса, number: новий результат]","answer":"[50%, 60%, 30%, 18, 2.975, 126, -6]","decision":"облік за викупом","evidence":"три різні знаменники або підписані бази","nextStep":"звірити причину двох сторнувань","wrongAnswer":"20 × 12. Договір платить за зарахований викуп."}]},"3.1.3":{"prompt":"**TOV-03 · Воронка.** Для вигаданої польської пропозиції складаної підставки перший кадр ставить питання, чи підійде вона до вузького столу. Картки: «огляд із заміром», «оголошення», «форма із зайвим полем про місце роботи», «лендинг із розмірами й умовами», «форма з необхідними полями», «сторінка подяки з очікуванням дзвінка», «таймер без доказу». Розклади потрібні картки від контакту до завершення. Відкинь дві зайві й запиши, що має показати негативний тест форми.","exercises":[{"id":"TOV-03","types":["Воронка"],"states":"[бриф про вимірювання, сім карток без порядку]","input":"[order: п’ять кроків, select: дві зайві картки, text: доказ негативного тесту]","answer":"[оголошення, огляд із заміром, лендинг, необхідна форма, подяка, зайве поле і таймер, підказка без заявки]","decision":"послідовність з оглядом для заданого питання","evidence":"розміри до форми","nextStep":"негативний контроль форми","wrongAnswer":"Поставити форму перед доказом розміру. Людина не отримує відповіді до дії."}]},"3.1.4":{"prompt":"**TOV-04 · Модератор.** У незалежного вигаданого офера складаної підставки є фактичні заміри, комплект без чохла й оплата при отриманні. Для кожної картки зроби свайп «пропустити» або «відхилити» та обери причину: точний доказ, перебільшення, підміна, прихована умова, удавана терміновість або вигаданий відгук. Для карток 3 і 4 знайди слово, яке змінює рішення.\n\n| № | Картка |\n|---|---|\n| 1 | Та сама модель з рулеткою й читабельною шкалою |\n| 2 | У ролику дорожча модель, у посилці базова |\n| 3 | «Підходить до цих двох моделей», обидві перевірено |\n| 4 | «Підходить до всіх моделей», перевірено лише дві |\n| 5 | Чохол окремо, це видно в ролику та умовах |\n| 6 | Чохол «у комплекті», але продавець продає його окремо |\n| 7 | Напис «останні 10 хвилин» щоразу запускається заново |\n| 8 | Вигадана покупчиня подає сценарій як власний відгук |\n| 9 | Показано звичайну демонстрацію без заяв про досвід покупців |\n| 10 | Оголошення обіцяє післяплату, а сторінка вимагає передоплату |","exercises":[{"id":"TOV-04","types":["Модератор"],"states":"[10 окремих карток і шість причин, пари 3 і 4 та 5 і 6]","input":"[swipe: пропустити або відхилити для кожної, choice: причина, text: зміна слова 3–4]","answer":"[1 пропустити, 2 відхилити, 3 пропустити, 4 відхилити, 5 пропустити, 6 відхилити, 7 відхилити, 8 відхилити, 9 пропустити, 10 відхилити]","decision":"10 правильних свайпів","evidence":"обсяг доказу і фактичні умови для кожної картки","nextStep":"замінити одну хибну заяву готовою правкою","wrongAnswer":"Пропустити 4 через наявність двох замірів. Доказ не охоплює слово «всіх»."}]},"3.1.5":{"prompt":"**TOV-05 · Діагноз.** У вигаданого офера підставок контрольна заявка Q-52 має клік K-52. Партнер зарахував її, але вихідний постбек містить `subid=K-25`, а конверсія записана на K-25. Варіанти діагнозу: затримка, втрата кліка у формі, неправильне поле в постбеку. Обери діагноз і перший контроль: перевірити підстановку у вихідному запиті, чекати холду або змінити креатив.","exercises":[{"id":"TOV-05","types":["Діагноз"],"states":"[журнал кліка і заявки, вихідний постбек, рядок конверсії]","input":"[choice: діагноз, choice: перша перевірка, text: доказ повтору]","answer":"[неправильне поле в постбеку, перевірити підстановку, той самий новий ID у партнерці і трекері]","decision":"знайти розбіжність після запису заявки","evidence":"K-52 проти K-25","nextStep":"новий контроль без подвоєння","wrongAnswer":"Чекати холду. Технічна розбіжність уже видима."}]},"3.1.6":{"prompt":"**TOV-06 · Знайди блокер.** Вигаданий кейс продає сушарку у Польщі. Обери перший рядок, який заважає прийняти заяву про знижку.\n\n| Рядок | Факт |\n|---|---|\n| 1 | Назва продавця і модель збігаються |\n| 2 | Для «було $60» є один скрин, повної історії цін немає |\n| 3 | Спосіб і строк доставки показано |\n| 4 | Підтвердження замовлення містить контакт підтримки |\n\nПісля вибору назви доказ для повторної перевірки. Якщо продавець не надасть його, запиши правку оголошення.\n\n**TOV-09 · Діалог.** Продавець сушарки пише в чаті: «Поставте в рекламу “−50%, лише сьогодні” і відгук пані Анни — у нас так усі роблять». У тебе є картка з фактичною ціною $41 і більше нічого. Напиши відповідь із трьох речень: що не можна опублікувати, який доказ потрібен для кожного твердження і що можна поставити замість.","exercises":[{"id":"TOV-06","types":["Знайди блокер"],"states":"[чотири рядки перевірки, заява про знижку]","input":"[tap_row: 1–4, text: необхідний доказ або правка]","answer":"[2, історія ціни за застосовний період для товару і продавця або прибрати заяву]","decision":"рядок 2","evidence":"одного знімка недостатньо","nextStep":"звірити правило і повторити перегляд","wrongAnswer":"Пропустити картку через видиму доставку."},{"id":"TOV-09","types":["Діалог"],"states":"[чат із продавцем, картка з ціною $41]","input":"[text: відповідь продавцю з трьох речень]","answer":"[без доказу знижки й строку та без підтвердженого відгуку публікація неможлива; потрібні найнижча ціна за 30 днів, справжній строк акції, оригінал відгуку зі згодою; замість — фактична ціна і доказова характеристика]","decision":"відмова від трьох тверджень без доказів","evidence":"названо доказ для кожного","nextStep":"безпечна заміна і строк для документів","wrongAnswer":"Погодитися, бо продавець відповідає за свій товар."}]},"3.1.7":{"prompt":"**TOV-07 · День за днем.** Вигаданий офер органайзерів має ціну $36 і платить $10 за підтвердження. У перший день варіант A витратив $12 без заявок. Межа CPL $4, правило паузи — три межі без заявки. У другому зрізі варіант B має 12 прийнятих заявок, шість зарахувань і $48 загальних витрат. У третій день капа 10, уже зараховано вісім, очікується ще дві дії. Вибери дію для кожного зрізу та порахуй результат B.","exercises":[{"id":"TOV-07","types":["День за днем"],"states":"[поріг і перший день, зрілий B, зайнята капа]","input":"[choice: перша дія, number: результат, choice: масштаб або пауза]","answer":"[пауза A і контроль маршруту, 12, новий обсяг відкласти]","decision":"застосувати різні критерії ризику і зрілості і капи","evidence":"12 і нуль та 6 зарахувань і 10 потенційно зайнятих","nextStep":"перевірити залишок після скидання","wrongAnswer":"Масштабувати B за прибутком і пропустити зайняту капу."}]},"3.1.F":{"prompt":"**TOV-08 · Воронка + Журнал + Порахуй.** Здай коротке досьє, яке інший баєр зможе відтворити. Спочатку працюй лише з картками й журналом до запуску. Наступні зрізи відкривай по черзі.\n\n| Поле | A. Органайзер Przystań | B. Органайзер Półka |\n|---|---|---|\n| GEO і мова | Польща, польська сторінка та кол-центр | Польща, польська сторінка |\n| Ціна покупця | $40 (≈160 PLN, покупець платить у злотих), післяплата | $42, післяплата |\n| Виплата | $12 за зарахований викуп | $15 за зарахований викуп |\n| Капа, обробка, холд | 10 викупів на добу, підтвердження до двох робочих днів, холд 10 календарних днів від зарахування | Капа та строки не підтверджені |\n| Канал і дублі | Meta Ads письмово дозволено; повтор того самого замовлення відсіюють до приймання | Письмово дозволено лише пошук |\n\nУ брифі мета — тест Meta Ads в Польщі. Покупець питає, чи органайзер стане на вузький стіл. Запропонуй один кут із доказом і розклади картки за ролями: оголошення, можливий огляд, лендинг, форма, післязаявочне підтвердження. Якщо лишаєш огляд, поясни, яке питання він закриває. Заява «підходить усім» і таймер без підтвердження не проходять контроль. Заміни їх точним описом. Окремо назви джерело для звірки чинних правил каналу та спосіб контрольної заявки до витрат.\n\n### Зріз 1. Контроль до витрат\n\n| Крок | Очікування | Факт |\n|---|---|---|\n| Кнопка | Показано саме органайзер A | Відкрився лендинг тієї самої моделі |\n| Умова оплати | Післяплата | У формі з’явився запит на передоплату |\n| Тестова заявка | У реєстрі той самий ID | У партнера QA-P1, у трекері повернений статус на QA-P0 |\n| Негативний тест | Порожня форма не створює запису | Помилка видима, запису немає |\n\nЗапиши два блокери, власників і докази повтору. Лише після свого рішення відкрий наступний абзац.\n\n**Підтверджений повтор у паперовому сценарії.** Продавець прибрав запит на передоплату. Нова форма показала післяплату, і партнер прив’язав статус до того самого нового ID, що трекер. Інші погоджені перевірки для цього навчального прогону пройшли. Реклама коштує $84, матеріали й сервіс $18. Усе сплачено до зарахування й виплати. Запиши касову потребу та три дати, які треба запитати для звіту.\n\n### Зріз 2. Ранній звіт\n\nІз 30 прийнятих заявок 9 підтверджено, 7 відхилено, 14 ще в роботі. Два викупи вже зараховано. Порахуй поточне нарахування й частку підтверджень із двома базами: серед усіх прийнятих і серед уже оброблених. Вибери між рішеннями: збільшити витрати за раннім підсумком, відкласти фінансовий висновок до дозрівання або перепідписати договір. Назви доказ, якого бракує.\n\nПеред відкриттям зрілого звіту познач можливу розбіжність: закритий статус дзвінка і остаточна оплата після доставки мають різні строки. Якщо партнер закрив обробку, а частина посилок ще в дорозі, запитай дату наступного зрізу доставки. У таблиці не змішуй залишок капи нового дня з показниками попередньої групи.\n\n### Зріз 3. Зрілий звіт\n\nІз тих самих 30 заявок стало 18 підтверджених, 10 викуплених, усі 10 викупів зараховано. Заповни апрув, викуп від підтверджених, наскрізну частку, фінансовий результат, фактичний CPL і межу рекламного CPL. Після цього відкрий дані для нового дня: вісім викупів уже зараховано, ще дві дії можуть зарахуватися до скидання. Запиши рішення щодо збільшення обсягу. Запропонуй один наступний крок із відповідальним і доказом.","exercises":[{"id":"TOV-08","types":["Воронка","Журнал","Порахуй"],"states":"[дві картки, блокери до тесту, підтверджений повтор, ранній зріз, зрілий зріз і капа]","input":"[choice: офер, order: ролі маршруту, journal: два блокери та повтор, number: каса і ранній звіт, number: зрілі частки і результат та CPL, text: наступна дія]","answer":"[A, передоплата і неправильний ID, 102, 24, 30%, 56.25%, 60%, 55.56%, 33.33%, 18, 2.8, 3.4, відкласти збільшення до звірки капи]","decision":"A і дві передзапускові паузи та зрілий висновок","evidence":"записи повтору і коректні бази","nextStep":"перевірити капу і касу до нового обсягу","wrongAnswer":"Множити 18 підтверджень на 12. Виплату дає зарахований викуп."}]},"3.2.1":{"prompt":"**NUT-01 · Оціни офер.** A — вигаданий польський крем для рук із підтвердженим складом і ритуалом догляду, ціна $30 (≈120 PLN), $9 за викуп, Meta дозволено мережею. B — добавка за $45, ставка $18 за продаж, чернетка каже, що вона замінює ліки. C — підписка $38 за місяць, ставка $10 за перший платіж, умови наступного списання приховані. Обери офер до підготовки, вкажи причини для двох інших і потрібний доказ до витрат.\n\n**NUT-09 · Діалог.** Менеджер партнерки пише: «Скрипт не чіпай, оператори продають як уміють. Фраза “допомагає при дерматиті” дає +15% апруву». Картка й етикетка описують Mâini de Seară як косметичний бальзам. Напиши менеджеру відповідь із трьох речень: чому тест не стартує, що саме має змінитися і як ти перевіриш зміну.","exercises":[{"id":"NUT-01","types":["Оціни офер"],"states":"[бриф Meta у Польщі, три картки продукту й умов]","input":"[choice: офер, text: дві причини паузи та перевірка до витрат]","answer":"[A, B лікувальна заява, C приховані списання]","decision":"A до підготовки","evidence":"відповідність класу і маршруту","nextStep":"звірити актуальні правила та фактичну сторінку","wrongAnswer":"Вибрати B за ставкою, проігнорувавши заяву про заміну лікування."},{"id":"NUT-09","types":["Діалог"],"states":"[чат із менеджером, картка й етикетка косметики]","input":"[text: відповідь із трьох речень]","answer":"[медична заява в скрипті суперечить класу продукту й рекламі; прибрати фразу зі скрипту письмово; контрольний дзвінок і запис]","decision":"тест на паузі до правки скрипту","evidence":"косметика не може обіцяти лікування дерматиту","nextStep":"письмове підтвердження і контрольний дзвінок","wrongAnswer":"Погодитися, бо вищий апрув покриє ризик."}]},"3.2.2":{"prompt":"**NUT-02 · Порахуй.** Вигаданий офер крему в США: ціна $36, ставка $12 за зарахований викуп. Із 36 прийнятих заявок 18 підтверджено, 12 викупів зараховано. Реклама $90, сервіс $18, окремі невідшкодовані витрати $12. Усе сплачено до виплати. Порахуй три частки, межу рекламного CPL, результат і касу. Як зміниться результат після сторнування трьох викупів?","exercises":[{"id":"NUT-02","types":["Порахуй"],"states":"[ціна і ставка за викуп, зрілий звіт, витрати, три сторнування]","input":"[number: три частки, number: межа CPL і каса та результат, number: результат після сторнування]","answer":"[50%, 66.67%, 33.33%, 3.1667, 120, 24, -12]","decision":"рахувати за викупом","evidence":"точні бази і всі статті","nextStep":"звірити сторнування в реєстрі","wrongAnswer":"Ігнорувати 12 доларів невідшкодованих витрат. Умови виділяють їх окремо."}]},"3.2.3":{"prompt":"**NUT-03 · Воронка.** Вигаданий офер мила показує в оголошенні упаковку й запрошує прочитати про склад. Розклади картки: оголошення, огляд із підписом продавця, лендинг зі складом і ціною, форма замовлення, подяка з поясненням доставки, анкета про діагнози, вигадане інтерв’ю лікаря. Вилучи зайві та назви очікування негативного тесту.","exercises":[{"id":"NUT-03","types":["Воронка"],"states":"[бриф та сім карток]","input":"[order: п’ять етапів, select: дві зайві, text: контроль]","answer":"[оголошення, підписаний огляд, лендинг, форма, подяка, вилучити анкету й інтерв’ю]","decision":"доказ до заявки","evidence":"прозоре авторство і склад","nextStep":"негативний контроль форми","wrongAnswer":"Поставити вигаданого лікаря перед формою. Авторство й доказ відсутні."}]},"3.2.4":{"prompt":"**NUT-04 · Модератор.** Вигаданий офер косметичного крему. Документація підтверджує склад і зовнішнє застосування. Вибери «пропустити» або «відхилити» для кожної картки. Причини: доказ, лікувальна заява, тиск на самосприйняття, підміна, авторство або прихована умова.\n\n| № | Картка |\n|---|---|\n| 1 | Той самий тюбик, читабельний склад з етикетки |\n| 2 | «Вилікує екзему», підтверджено лише склад |\n| 3 | «Для зовнішнього догляду», саме це в інструкції |\n| 4 | «Для лікування шкіри», інструкція описує лише догляд |\n| 5 | Показано нанесення без заяви про результат |\n| 6 | «Соромишся своїх рук?» із принизливим титром |\n| 7 | Ім’я лікаря без підтвердженої участі або дозволу |\n| 8 | Оплата при отриманні, та сама умова на сторінці |\n| 9 | У ролику один тюбик, у формі обов’язковий дорожчий набір |\n| 10 | Хімічний склад візуально підмінено іншою етикеткою |\n\nПорівняй 3 і 4. Яке слово потребує зовсім іншого доказу? Пропуск у вправі означає проходження наведених перевірок.","exercises":[{"id":"NUT-04","types":["Модератор"],"states":"[десять карток, список причин]","input":"[swipe: пропустити або відхилити кожну, choice: причина, text: відмінність 3 і 4]","answer":"[1 так, 2 ні, 3 так, 4 ні, 5 так, 6 ні, 7 ні, 8 так, 9 ні, 10 ні]","decision":"десять свайпів","evidence":"клас і доказ або ризик","nextStep":"звузити заяву до підтвердженого догляду","wrongAnswer":"Пропустити 4, бо є інструкція. У ній немає лікувального твердження."}]},"3.2.5":{"prompt":"**NUT-05 · Діагноз.** У вигаданому офері крему партнер правильно записав викуп N-51. У рекламній події видно квізову категорію «діагноз» і тестове значення. Вибери діагноз: затримка виплати, зайва передача даних або втрачений click ID. Обери перший контроль: зупинити передачу й перевірити фактичні поля, змінити ставку або чекати виплати. Назви доказ повтору.","exercises":[{"id":"NUT-05","types":["Діагноз"],"states":"[кінцевий факт викупу, синтетичне повідомлення із зайвим полем]","input":"[choice: діагноз, choice: перша дія, text: доказ повтору]","answer":"[зайва передача, зупинити передачу та звірити поля, чисте повідомлення в контрольному тесті]","decision":"зупинка джерела","evidence":"поле опинилось у фактичній передачі","nextStep":"перевірити повтор без зайвих даних","wrongAnswer":"Змінити назву поля. Передача значення лишиться."}]},"3.2.6":{"prompt":"**NUT-06 · Знайди блокер.** Для вигаданої добавки в Польщі торкнися першого рядка, через який не можна прийняти заяву.\n\n| Рядок | Факт |\n|---|---|\n| 1 | Етикетка і товар збігаються |\n| 2 | Чернетка обіцяє схуднення на конкретну кількість за тиждень |\n\n| Рядок | Факт |\n|---|---|\n| 3 | Продавця видно до оплати |\n| 4 | Спосіб звернення вказано |\n\nЗапиши, що повернеш редактору і який документ перевіриш перед повтором.","exercises":[{"id":"NUT-06","types":["Знайди блокер"],"states":"[чотири інтерактивні рядки, клас харчової добавки]","input":"[tap_row: 1–4, text: правка і джерело]","answer":"[2, прибрати обіцянку темпу або величини схуднення, ст. 12 Регламенту 1924/2006]","decision":"перша неприпустима заява","evidence":"точна фраза і клас","nextStep":"повторна звірка законності і політики","wrongAnswer":"Пропустити заяву через правильну етикетку."}]},"3.2.7":{"prompt":"**NUT-07 · День за днем.** Вигаданий офер крему для зовнішнього догляду: $35 ціна, $10 за зарахований викуп. День 1: $9 реклами, жодної прийнятої заявки, межа CPL $3 і правило трьох меж. День 2: форму виправили. Тестовий дзвінок усе ще вимагає купити дорожчий набір, якого немає в рекламі. Фінальний зріз попередньої групи: дев’ять зарахованих викупів, $85 витрат. Запиши рішення для кожного зрізу та фінансовий підсумок.","exercises":[{"id":"NUT-07","types":["День за днем"],"states":"[три послідовні зрізи]","input":"[choice: перша пауза, choice: рішення після дзвінка, number: фінансовий результат, text: доказ перед відновленням]","answer":"[пауза і перевірка форми, пауза через підміну, 5, дзвінок і реєстр за початковою умовою]","decision":"не відновлювати за плюсом","evidence":"підміна підтверджена тестом","nextStep":"повтор з правильним замовленням","wrongAnswer":"Повернути витрати через плюс у зрілій групі."}]},"3.2.F":{"prompt":"**NUT-08 · Воронка + Журнал + Порахуй.** Вибери один офер для Meta в Польщі. Заповни маршрут і відкривай зрізи по черзі.\n\n| Поле | A. Nuta Krem | B. Zestaw Dnia |\n|---|---|---|\n| Клас і ціна | Крем для зовнішнього догляду, $40 (≈160 PLN, покупець платить у злотих), післяплата | Добавка за $46, у чернетці заява про заміну лікування |\n| Оплачувана дія | $12 за зарахований викуп | $18 за зараховану покупку |\n| Капа, холд | 10 викупів на добу за часом Варшави, 12 календарних днів від зарахування | Не визначено |\n| Джерело | Meta Ads письмово дозволено мережею для Польщі | Джерело не підтверджено |\n| Виконання | Кол-центр польською, до двох робочих днів, дубль замовлення вилучають до приймання | Заяви й місцеву інформацію ще не звірено |\n\nОбери один кут, назви джерело доказу і розклади картки «оголошення», «огляд або квіз», «лендинг», «форма» й «подяка». Огляд можна пропустити, якщо креатив уже відповідає на питання. Якщо є квіз, він лише веде до потрібного розділу. Назви, що покупець має прочитати до першого поля форми. Для негативного тесту вкажи, що зробиш і як перевіриш відсутність нового запису.\n\n### Зріз 1. Блокери перед тестом\n\n| Крок | Очікування | Факт |\n|---|---|---|\n| Оголошення і сторінка | Опис зовнішнього догляду підтверджено | Преленд каже «лікує шкіру за п’ять днів» |\n| Сторінка подяки | В аналітику йдуть лише потрібні поля | Вихідна тестова подія містить старе поле про симптоми |\n| Форма | Створено одну заявку з правильним ID | Правильний запис з’явився |\n| Умови | Післяплата та ціна збігаються | Пройдено |\n\nНазви два блокери, власників і доказ повтору. Для контенту зафіксуй точну фразу і редакцію сторінки. Для передачі даних запиши назву зайвого поля без його значення та зупини передачу до повтору. Після правки власники показали узгоджений текст у ролику, огляді та дзвінку, а в тестовому повідомленні немає зайвого поля. За умовами паперового сценарію інші перевірки пройшли.\n\n### Зріз 2. Ранній звіт\n\nРеклама $108, матеріали й сервіс $24. Усе сплачено до переказу. Прийнято 36 заявок, 12 підтверджень, 8 відмов і 16 заявок в обробці. Чотири викупи вже зараховано. Порахуй касову потребу, поточне нарахування, апрув від усіх та від опрацьованих. Назви доказ для наступного рішення. Гроші, які ще на холді, у касу не включай.\n\n### Зріз 3. Зрілий звіт\n\nДля тих самих 36 заявок підтверджено 20, викуплено й зараховано 13. Витрати лишилися ті самі. Порахуй три частки, результат, фактичний CPL і межу рекламного CPL. У новому дні є сім зарахувань і три можливі до скидання капи. Запиши рішення про новий тест.\n\n### Перевір досьє перед здачею\n\nПеред ключем перевір джерело кожного числа. Сума нарахування виникла з викупів, рекламний CPL — із прийнятих заявок. Якщо називаєш частку підтверджень, підпиши, чи включено всі заявки або тільки опрацьовані. За нового дня залишок капи є окремим рішенням, навіть якщо стара група прибуткова. Запиши день витрат, день нарахування й день надходження. Якщо фактична дата переказу відсутня, попроси платіжний доказ після холду. У короткій записці до власника офера сформулюй, який доказ дасть право переглянути паузу та хто має його надати.","exercises":[{"id":"NUT-08","types":["Воронка","Журнал","Порахуй"],"states":"[картки, блокери, повтор, ранні та зрілі дані і нова капа]","input":"[choice: офер, order: маршрут, journal: блокери та повтор, number: каса і ранні показники, number: зрілі показники, text: фінальне рішення]","answer":"[A, лікування і зайва передача, 132, 48, 33.33%, 60%, 55.56%, 65%, 36.11%, 24, 3, 3.6667, пауза нового обсягу]","decision":"A з двома блокерами і паузою до доказів","evidence":"зіставлені статуси і правильні знаменники","nextStep":"звірити капу та фактичний переказ","wrongAnswer":"Вважати 20 підтверджень оплачуваними."}]},"3.3.1":{"prompt":"**ECOM-01 · Оціни офер.** Потрібен тест у Чехії. A — власний магазин підставок із місцевим складом і підтвердженим замовленням. B — дропшиппінг із невизначеним строком та відсутньою адресою повернення. C — CPS, ціна $45 (≈1 035 CZK), ставка $10, письмово дозволено лише пошук. Для тесту потрібен Meta Ads. Вибери офер, укажи блокери інших і один доказ до витрат.","exercises":[{"id":"ECOM-01","types":["Оціни офер"],"states":"[три моделі і бриф Meta в Чехії]","input":"[choice: картка, text: два блокери і доказ]","answer":"[A, B виконання, C джерело]","decision":"A до підготовки","evidence":"локальний склад і контроль","nextStep":"повторити шлях та перевірити права і правила","wrongAnswer":"C через видиму ставку. Договір не дозволяє потрібного джерела."}]},"3.3.2":{"prompt":"**ECOM-02 · Порахуй.** Вигаданий магазин полиць: $50 за товар, 8 оплат і $400 списань. Окремі повернення та остаточні спори $50 і $50. Змінні витрати $180, реклама $100. Порахуй чисту виручку, внесок, чистий і граничний ROAS та результат. Що зміниться, якщо другий рядок віднімання має той самий ID і є дублем, а витрати сталі?","exercises":[{"id":"ECOM-02","types":["Порахуй"],"states":"[списання, два коригування, витрати, факт дубля]","input":"[number: виручка і внесок і два ROAS та результат, number: результат без дубля]","answer":"[300, 120, 3, 2.5, 20, 70]","decision":"виправити дубль за ID","evidence":"дві бази на чистій виручці","nextStep":"звірити платіжний журнал","wrongAnswer":"Взяти валові 400 для чистого ROAS."}]},"3.3.3":{"prompt":"**ECOM-03 · Воронка + Порахуй.** Магазин полиць рекламує вузьку модель за $45. Доставка $5, необов’язкова вставка $6. Впорядкуй картки: оголошення, товар із правильною моделлю, кошик, чекаут, підтвердження. Порахуй базову суму й суму зі вставкою. У тесті платіж відхилено, але система зберегла замовлення. Назви ознаку, за якою приймеш негативний контроль.\n\n**ECOM-09 · Діалог.** Розробник магазину пише: «Я поставив галочку “Додати гарантію 2 роки — $8” увімкненою за замовчуванням. Хто захоче — зніме. Це +$8 до чеку». Магазин продає лампи в Польщі. Напиши розробнику відповідь із трьох речень: що не так, що змінити і як перевірити.","exercises":[{"id":"ECOM-03","types":["Воронка","Порахуй"],"states":"[п’ять карток, ціна доставки й доповнення, негативний тест]","input":"[order: маршрут, number: дві суми, text: доказ негативного тесту]","answer":"[оголошення, товар, кошик, чекаут, підтвердження, 50, 56, немає успішної оплати]","decision":"маршрут і необов’язкове доповнення","evidence":"ціна і платіжний стан","nextStep":"перевірити контрольний ID та відсутність Purchase","wrongAnswer":"Зарахувати покупку за самим фактом створення замовлення."},{"id":"ECOM-09","types":["Діалог"],"states":"[повідомлення розробника, чекаут із галочкою]","input":"[text: відповідь із трьох речень]","answer":"[у ЄС додатковий платіж потребує явної згоди, увімкнена за замовчуванням галочка згодою не є; галочка вимкнена або окрема кнопка; тестове замовлення без дій покупця має суму без гарантії]","decision":"прибрати передвибір","evidence":"вимога явної згоди на додатковий платіж","nextStep":"тестове замовлення і перевірка суми","wrongAnswer":"Лишити, бо покупець може зняти галочку сам."}]},"3.3.4":{"prompt":"**ECOM-04 · Модератор.** Для вигаданого магазину настільних підставок обери «пропустити» або «відхилити». Додай причину з факту: звірено, підміна, хибна ціна, відгук без джерела або непідтверджена заява. Картки 3 і 4 перевіряють обсяг доказу.\n\n| № | Що показано |\n|---|---|\n| 1 | Точна модель, ціна й фото відповідають сторінці |\n| 2 | Оголошення показує чорну модель, кошик додає білу |\n| 3 | «Підійде до столів із цієї таблиці», усі перевірено |\n| 4 | «Підійде до всіх столів», перевірено лише таблицю |\n| 5 | Оплата й доставка збігаються в рекламі та чекауті |\n| 6 | Перекреслена ціна без підтвердження |\n| 7 | Власна демонстрація зборки з дозволом на використання |\n| 8 | Вигаданий відгук подано як справжній |\n| 9 | Креатив чесно описує, що кабель продається окремо |\n| 10 | Кнопка веде до обов’язкового дорожчого комплекту |","exercises":[{"id":"ECOM-04","types":["Модератор"],"states":"[десять карток, перелік причин]","input":"[swipe: пропустити або відхилити, choice: причина, text: відмінність 3 і 4]","answer":"[1 так, 2 ні, 3 так, 4 ні, 5 так, 6 ні, 7 так, 8 ні, 9 так, 10 ні]","decision":"десять свайпів","evidence":"опис і фактична сторінка","nextStep":"виправити твердження або підміну","wrongAnswer":"Пропустити 4 через наявність таблиці."}]},"3.3.5":{"prompt":"**ECOM-05 · Діагноз.** У вигаданому магазині підставок одне замовлення S-47 і успішний платіж. Pixel показує Purchase з ID S-47, CAPI — Purchase з ID S-74. Вибери діагноз: неузгоджена дедуплікація, два платежі або відмова провайдера. Обери першу перевірку та поясни, що приймеш у повторі.","exercises":[{"id":"ECOM-05","types":["Діагноз"],"states":"[один успішний платіж і два повідомлення з різними ID]","input":"[choice: діагноз, choice: перша звірка за ID замовлення або платіжною затримкою, text: доказ повтору]","answer":"[неузгоджена дедуплікація, карта ID, одна покупка за однаковим ключем]","decision":"перевірити джерело ID","evidence":"один платіж та різні ID","nextStep":"повторити з новою тестовою покупкою","wrongAnswer":"Вважати два повідомлення двома оплатами."}]},"3.3.6":{"prompt":"**ECOM-06 · Знайди блокер.** Для вигаданого магазину полиць у Чехії торкнися першого рядка, де шлях втрачає підтверджену повну ціну.\n\n| Рядок | Факт |\n|---|---|\n| 1 | Продавця й модель підтверджено |\n| 2 | Магазин рекламує повну ціну, але можливу обов’язкову доплату повідомляють тільки при отриманні |\n| 3 | Є контакт і процедура повернення |\n\n| Рядок | Факт |\n|---|---|\n| 4 | У тесті відкривається та сама модель |\n\nНазви доказ і власника правки.","exercises":[{"id":"ECOM-06","types":["Знайди блокер"],"states":"[чотири рядки маршруту]","input":"[tap_row: 1–4, text: доказ та власник]","answer":"[2, повна сума до замовлення, продавець і відповідальний за доставку]","decision":"блокер ціни","evidence":"доплату видно запізно","nextStep":"звірити суму і повторити чекаут","wrongAnswer":"Рядок 3. Контакт для повернення не розкриває ціну."}]},"3.3.7":{"prompt":"**ECOM-07 · День за днем.** Вигаданий магазин підставок. День 1: 14 одиниць, шість зарезервовано. Склад виконує до семи на добу, п’ять уже в черзі. День 2: з $90 доступної каси потрібні $24 реклами та $25 на замовлення. День 3: провайдер відкладає виплату, а три нові скарги вказують на іншу модель. Назви межі, рішення та доказ для повтору.","exercises":[{"id":"ECOM-07","types":["День за днем"],"states":"[залишки й черга, каса, затримка і скарги]","input":"[number: вільний сток та черга, number: касовий максимум, choice: дія, text: повтор]","answer":"[8, 2, 2, пауза, платіжний залишок і збіг моделі]","decision":"пауза після скарг","evidence":"сток і черга та каса пораховані","nextStep":"фактичний контроль варіанта й доступного переказу","wrongAnswer":"Планувати вісім замовлень за залишком стоку."}]},"3.3.F":{"prompt":"**ECOM-08 · Воронка + Журнал + Порахуй.** Команда хоче протестувати Meta Ads у Польщі на одному товарі. Створи план від оголошення до фактичного рішення про повтор. Відкривай зрізи по черзі.\n\n| Поле | A. Stojak Równo | B. Półka Pracy |\n|---|---|---|\n| Модель | Власний магазин підставок, польський склад | CPS за продаж підставки |\n| Ціна | $50 (≈200 PLN, покупець платить у злотих), онлайн | $65, комісія $14 за зарахований продаж |\n| Джерело й виконання | Meta допускається в навчальній картці після контролю, склад і повернення підтверджено | Дозволено лише пошук, після повернень остаточний реєстр надає партнер |\n| Обмеження | П’ять нових замовлень на добу, провайдер платить за графіком | Капа й холд невідомі |\n\nВибери офер і підпиши, що підтверджує дохід у кожній моделі. Для A напиши кут про ширину основи та джерело доказу. Упорядкуй картки: оголошення, картка товару, кошик, чекаут, підтвердження. У чекауті запиши одне правило для необов’язкового доповнення. Для контролю доставки назви, де покупець бачить повну суму до оплати.\n\n### Зріз 1. Контроль перед спендом\n\n| Крок | Очікування | Факт |\n|---|---|---|\n| Оголошення й товар | Графітовий варіант | Картка відкрилася у потрібному кольорі |\n| Кошик і чекаут | Графітовий варіант і та сама ціна | Кошик змінив колір на білий |\n| Негативна оплата | Відхилений платіж без успішної Purchase | Purchase з’явилася після відмови |\n| Повернення | Доступний контакт продавця | Контакт видно |\n\nЗапиши два блокери і власників. Для повтору вкажи два тести: успішну покупку з правильним товаром та негативний чекаут без успішної події. Лише після відповіді відкрий повтор. За паперовим сценарієм власник магазину відтворив правильний варіант у кошику, а власник вимірювання показав коректні події для успіху й відмови. Інші перевірки в навчальній картці закриті.\n\n### Зріз 2. Ранній звіт\n\nДесять покупок по $50 дали $500 валових списань. Одне повернення на $50 підтверджено. Витрати на товар, виконання та комісії $245, реклама $140. Спір на $50 ще відкритий. Порахуй ранню чисту виручку, ранній результат і валовий ROAS. Назви суму, яка може змінити виручку та результат. Усі гроші на закупівлю $175, виконання $50 та рекламу $140 сплачено до виплати. Платіжні комісії утримує провайдер. Порахуй касову потребу за вказаних умов. Зазнач, що потреба до виплати і повні витрати звіту можуть різнитися через момент утримання комісій.\n\n### Зріз 3. Зрілий звіт\n\nСпір програно, він стосується іншого платежу, ніж повернення. Провайдер утримав ще $15 збору за спір. Зведи чисту виручку, внесок, чистий ROAS, поріг ROAS і підсумок. Для нового дня є чотири одиниці, одна зарезервована, склад уже має три заплановані замовлення з денного максимуму п’ять. Після підтвердженої виплати на новий тест доступно $60. План реклами $20, товар і виконання по $25 на замовлення. Порахуй три стелі й визнач доказ перед повтором.\n\n### Перевір бланк перед здачею\n\nУ фінансовому досьє залиш день витрат, день оплати покупцем та день фактичного надходження окремо. Відкритий спір може впливати на платіжний залишок до остаточного рішення. У цьому кейсі зрілий зріз дає факт втрати. Якщо у твоєму записі ранній і зрілий спенд різняться, повернись до брифу та звір межі групи. Якщо каса або склад можуть виконати тільки одну покупку, поясни, як обмежиш фактичне приймання замовлень. Рекламний бюджет сам не забезпечує точну кількість продажів.","exercises":[{"id":"ECOM-08","types":["Воронка","Журнал","Порахуй"],"states":"[дві картки, контроль, повтор, ранній звіт, зрілий звіт і залишки]","input":"[choice: офер, order: маршрут, journal: два блокери і докази, number: рання економіка і каса, number: зріла економіка та три стелі, text: рішення]","answer":"[A, варіант і хибна Purchase, 450, 65, 3.57, 365, 400, 140, 2.86, 2.86, 0, 3, 2, 1]","decision":"A і пауза до повтору та обсяг тільки в межах каси","evidence":"статуси платежів і стелі пораховано","nextStep":"прийняти одну покупку тільки за гарантованого контролю обсягу","wrongAnswer":"Масштабувати за валовим ROAS без перевірки спору і каси."}]},"3.4.1":{"prompt":"**DAT-01 · Оціни офер.** Вибери маршрут для підготовки Meta у Польщі. A — пошук за інтересами, $24 за місяць (≈96 PLN), $5 за DOI, видно умови, дозвіл акаунта ще перевіряють. B — $7 за реєстрацію до платного чату, профілі ведуть оператори під виглядом користувачів. C — $10 за прийняту оплату плану $28, автоподовження приховано. Назви рішення для кожного й доказ до спенду.","exercises":[{"id":"DAT-01","types":["Оціни офер"],"states":"[три картки та бриф]","input":"[choice: картка, text: дві причини і доказ]","answer":"[A до підготовки, B відхилити, C пауза]","decision":"A без запуску","evidence":"фактичний сервіс і підписка","nextStep":"підтвердити допуск акаунта","wrongAnswer":"Запустити A, бо умови оплати видимі."}]},"3.4.2":{"prompt":"**DAT-02 · Порахуй.** У вигаданому сервісі спілкування план коштує $24, баєру платять $5 за зарахований DOI. Є 30 прийнятих реєстрацій, 18 DOI і 6 перших оплат серед цих DOI. Реклама $60, супутні витрати $15. Порахуй три частки, нарахування, межу рекламного CPL і результат. Потім партнер сторнує чотири DOI серед записів без оплати. Порахуй новий фінансовий результат.","exercises":[{"id":"DAT-02","types":["Порахуй"],"states":"[зрілий звіт, умова виплати, окремий зріз зі сторнуванням]","input":"[number: три частки, number: нарахування й межа CPL і результат, number: підсумок після коригування]","answer":"[60%, 33.33%, 20%, 90, 2.50, 15, -5]","decision":"ставку застосовано лише до DOI","evidence":"знаменники підписано","nextStep":"звірити чотири сторнування у фінальному звіті","wrongAnswer":"Множити усі 30 реєстрацій на 5 доларів."}]},"3.4.3":{"prompt":"**DAT-03 · Воронка.** Для вигаданого сервісу знайомств за настільними іграми впорядкуй п’ять карток: оголошення, квіз про доступні функції, реєстрація, підтвердження пошти, прозорий платний план. Вилучи дві зайві: питання про інтимне життя і платіж до показу автоподовження. Запиши очікування повторного відкриття листа та доказ скасування.","exercises":[{"id":"DAT-03","types":["Воронка"],"states":"[сім карток і умови DOI та підписки]","input":"[order: п’ять етапів, select: дві зайві картки, text: два контрольні докази]","answer":"[оголошення, квіз, реєстрація, підтвердження, план, вилучити інтимне питання й ранню оплату, один DOI та вимкнене продовження]","decision":"умови видно до платежу","evidence":"один зарахований DOI й стан підписки","nextStep":"перевірити обидві дії окремо","wrongAnswer":"Поставити платіж до пояснення ціни й продовження."}]},"3.4.4":{"prompt":"**DAT-04 · Модератор.** Окремий вигаданий сервіс для дорослих знайомств за книжковими інтересами. Вибери «пропустити» або «відхилити» за фактичним змістом. Пропуск означає проходження перевірки цієї вправи.\n\n| № | Картка |\n|---|---|\n| 1 | Позначене демо вибору книжкових жанрів, функцію підтверджено |\n| 2 | Вигадана анкета видана за користувача, який уже написав |\n\n| № | Картка |\n|---|---|\n| 3 | «Пошук за спільними інтересами», той самий фільтр у сервісі |\n| 4 | Та сама фраза, фільтра на сторінці й у сервісі немає |\n| 5 | «Тобі 45 і ти самотній» |\n| 6 | Показано нейтральне налаштування вікового діапазону |\n| 7 | Обіцяно сексуальну зустріч |\n| 8 | Платну функцію названо безоплатною |\n| 9 | Ціна й період збігаються з умовами на сторінці |\n| 10 | У ролику видно чужі приватні повідомлення без погоджених прав |","exercises":[{"id":"DAT-04","types":["Модератор"],"states":"[десять окремих карток і підтвердження функцій з брифу]","input":"[swipe: пропустити або відхилити, choice: причина, text: різниця карток 3 і 4]","answer":"[1 так, 2 ні, 3 так, 4 ні, 5 ні, 6 так, 7 ні, 8 ні, 9 так, 10 ні]","decision":"десять свайпів","evidence":"доказ функції й прозорість умов","nextStep":"звірити оновлений матеріал і сторінку","wrongAnswer":"Пропустити 4, бо текст ідентичний 3. Доказ функції відсутній."}]},"3.4.5":{"prompt":"**DAT-05 · Діагноз.** У вигаданому сервісі R-73 прийнято і підтверджено вчасно. У партнера зараховано DOI за K-73, але вихідний постбек повертає K-37. Обери причину: затримка листа, підстановка чужого ключа або повернення підписки. Назви першу перевірку й доказ повтору.\n\n**DAT-08 · Діалог.** Менеджер каже: «R-63 є в реєстрі, просто вважай усі підтвердження зарахованими». Партнер підтвердив один DOI за R-63. У трекері події немає, статуси інших рядків відкриті. Напиши три речення: що зарахуєш зараз, який доказ попросиш і як перевіриш правку.","exercises":[{"id":"DAT-05","types":["Діагноз"],"states":"[запис реєстрації, реєстр DOI, вихідний постбек]","input":"[choice: причина, text: перша перевірка і доказ повтору]","answer":"[підстановка чужого ключа, звірити джерело click ID, новий запис із тим самим ID у трекері та партнерки]","decision":"перевірити підстановку","evidence":"K-73 проти K-37","nextStep":"повторити новий DOI без дубля","wrongAnswer":"Чекати листа, хоча підтвердження вже є."},{"id":"DAT-08","types":["Діалог"],"states":"[повідомлення менеджера, реєстр і трекер]","input":"[text: три речення]","answer":"[зарахувати лише R-63, попросити технічний доказ, повторити контроль]","decision":"врахувати один DOI","evidence":"реєстр за R-63 і відсутній сигнал","nextStep":"перевірити доставлення та повтор","wrongAnswer":"Зарахувати всі підтвердження."}]},"3.4.6":{"prompt":"**DAT-06 · Знайди блокер.** У вигаданому польському сервісі перевір п’ять рядків. Торкнися першого незакритого доказу допуску. Після його виправлення знайди наступний блокер для покупця.\n\n| Рядок | Факт |\n|---|---|\n| 1 | Оператор і фактична сторінка збігаються |\n\n| Рядок | Факт |\n|---|---|\n|  |  |\n| 2 | Є дозвіл на інший рекламний акаунт |\n| 3 | Ціну й період видно до оплати |\n| 4 | Після скасування профіль показує наступне списання |\n| 5 | Контрольний сигнал містить тільки узгоджені технічні поля |","exercises":[{"id":"DAT-06","types":["Знайди блокер"],"states":"[п’ять рядків, після першої відповіді надано дозвіл для потрібного акаунта]","input":"[tap_row: перший і другий блокери, text: доказ повтору]","answer":"[2, 4, документ на фактичний маршрут та відсутність наступного списання]","decision":"два незалежні блокери","evidence":"акаунт і стан підписки","nextStep":"повторити перевірку дозволу й скасування","wrongAnswer":"Запустити після отримання дозволу, хоча скасування не спрацювало."}]},"3.4.F":{"prompt":"**DAT-07 · Воронка + Журнал + Порахуй.** Підготуй одну пропозицію для Meta в Польщі. Розкривай зрізи по черзі.\n\n| Поле | A. Czytamy Razem | B. List od Ciebie |\n|---|---|---|\n| Фактична послуга | Знайомства за книжковими інтересами, реальні анкети, польська підтримка | Чат з операторами, які видають себе за реальних користувачів |\n| Ціна й дія | $24 (≈96 PLN, покупець платить у злотих) за місяць. $5 за унікальний зарахований DOI, підтвердження пошти до 48 годин | $26 за місяць, $7 за прийняту реєстрацію |\n| Капа і переказ | 15 зарахувань на добу за Варшавою, 14 днів холду від зарахування | Строки не підтверджено |\n| Джерело | Мережа письмово дозволяє Meta після підтвердження дозволу платформи | Роль афіліата й джерело не підтверджені |\n\nВибери офер. Запиши кут із перевірною функцією. Впорядкуй оголошення, нейтральний квіз, реєстрацію, лист і платний план із видимим продовженням. Між листом і планом опиши, як користувач може залишитися на базовій версії. Перед оплатою він має прочитати суму, період і умови скасування. Додай негативний контроль: без підтвердження пошти зарахованого DOI немає.\n\n### Зріз 1. Два блокери\n\n| Рядок | Очікування | Факт |\n|---|---|---|\n| 1 | Допуск для акаунта | Документ надано для іншого акаунта |\n| 2 | Один зарахований DOI | Після повторного відкриття листа лишився один запис |\n| 3 | Вимкнене продовження | Лист підтверджує скасування, а профіль показує наступний платіж |\n| 4 | Мінімальні дані події | Передаються тільки погоджені технічні поля |\n\nЗапиши, хто виправляє кожний блокер і який доказ приймеш. Після здачі першої відповіді відкрий повтор: власник акаунта показав застосовний дозвіл для маршруту, а оператор провів нове скасування. У підтвердженні й профілі видно вимкнене продовження і немає запланованого платежу. Інші перевірки в паперовому кейсі прийняті. Повтор не створює нового зарахування.\n\n### Зріз 2. Ранній звіт\n\nРеклама коштувала $85, супутні витрати $15, усе сплачено до переказу. Із 40 прийнятих реєстрацій зараховано 12 DOI, 8 відхилено, 20 ще відкриті. Порахуй касову потребу, поточне нарахування й частку DOI серед закритих та від усіх прийнятих. Запиши, чого бракує для фінансового висновку. У тесті діє початковий ліміт, навіть якщо частка серед оброблених виглядає високою.\n\n### Зріз 3. Зрілий звіт\n\nТі самі 40 прийнятих реєстрацій дали 24 зарахованих DOI та шість перших оплат серед них. Порахуй фінальний результат, частку DOI, частку перших оплат від DOI, фактичний рекламний CPL та межу CPL. У новому дні вже зараховано 12 дій, ще три можуть зарахуватися до скидання. Окремо виріши, чи є місце для нового обсягу.\n\n### Перевір досьє до здачі\n\nУ фінансовому рядку збережи окремо день витрат, дату зарахування і фактичний переказ. Якщо остання дата невідома, запитай платіжний доказ після холду. Не додавай списання користувачів до комісії за DOI. Їх можна показати в окремому рядку як показник наступного етапу. Підпиши для кожної частки знаменник і дату зрізу. Перед рішенням про повтор попроси менеджера підтвердити поточний залишок капи й узгоджений час перерахунку. Позитивний результат ранньої групи не звільняє місця в наступній добі.","exercises":[{"id":"DAT-07","types":["Воронка","Журнал","Порахуй"],"states":"[дві картки, контроль, повтор, ранній і зрілий звіти, капа]","input":"[choice: офер, order: маршрут, journal: два блокери і повтор, number: ранні і зрілі показники, text: рішення]","answer":"[A, дозвіл і скасування, 100, 60, 60%, 30%, 20, 60%, 25%, 2.125, 2.625, відкласти обсяг]","decision":"A на підготовку і пауза до двох доказів","evidence":"правильні статуси й бази","nextStep":"повторити звірку капи та переказу","wrongAnswer":"Масштабувати за 24 DOI без перевірки сьогоднішньої капи."}]},"3.5.1":{"prompt":"**INFO-01 · Оціни офер.** A — польський курс презентацій за $80, ставка $16 за оплату після повернень, програма й тестовий доступ є, Meta письмово дозволено. B — книга за $35 і $8 за зараховану покупку, продавець не показує спосіб отримання. C — коучинг $120 за $25 комісії, обіцяє гарантований дохід. Обери картку до підготовки, назви два блокери й потрібний доказ перед витратами.","exercises":[{"id":"INFO-01","types":["Оціни офер"],"states":"[три картки і вимога Meta в Польщі]","input":"[choice: офер, text: причини відмови й контроль]","answer":"[A, B немає доказу надання, C гарантія доходу]","decision":"A для підготовки","evidence":"звірений продукт і канал","nextStep":"контрольна оплата та доступ","wrongAnswer":"C через вищу ставку. Обіцянка доходу не підтверджує навичку."}]},"3.5.2":{"prompt":"**INFO-02 · Порахуй.** Вигаданий курс коштує $75, партнер платить $15 після повної оплати та перевірки. Є 50 прийнятих реєстрацій, 25 учасників, п’ять зарахованих продажів. Реклама $55, сервіс $10. У графіку ще $90 внесків. Порахуй явку, дохід на реєстрацію, межу рекламного CPL, результат і касу. Потім один продаж сторновано. Що змінилося?\n\n**INFO-08 · Діалог.** Партнер пише: «У звіті сім зарахованих, але в чаті з’явилося ще одне повернення. Відніми його одразу». Витрати групи $108, ставка $18. Напиши, який результат поки підтверджено, що попросиш і як оновиш висновок.","exercises":[{"id":"INFO-02","types":["Порахуй"],"states":"[зрілий звіт і графік внесків, окреме сторнування]","input":"[number: явка, дохід на реєстрацію, межа, результат, каса, результат після сторнування]","answer":"[50%, 1.50, 1.30, 10, 65, -5]","decision":"рахувати тільки зараховані продажі","evidence":"підписані знаменники й витрати","nextStep":"звірити коригування у фінальному звіті","wrongAnswer":"Додати майбутні 90 доларів до доходу баєра."},{"id":"INFO-08","types":["Діалог"],"states":"[звіт і повідомлення про повернення]","input":"[text: відповідь у трьох реченнях]","answer":"[залишити +18 USD до звірки, попросити ID та версію, оновити після підтвердження]","decision":"зберегти поточний реєстр","evidence":"7 зарахувань по 18 USD та невідомий статус сторно","nextStep":"звірити включення коригування та дату","wrongAnswer":"Відняти повернення без перевірки."}]},"3.5.3":{"prompt":"**INFO-03 · Воронка.** Вигадана школа презентацій дає безоплатний шаблон, проводить записану демонстрацію та продає курс. Впорядкуй оголошення, реєстрацію, лист із шаблоном, позначений запис, сторінку продажу, оплату й доступ. Вилучи фальшивий чат і вимогу оплатити шаблон, оголошений безоплатним. У тесті платіж пройшов, а учневі відкрився інший тариф. Назви власника правки й доказ повтору.","exercises":[{"id":"INFO-03","types":["Воронка"],"states":"[сім етапів, дві зайві картки, факт помилкового тарифу]","input":"[order: етапи, select: зайві картки, text: власник і контроль]","answer":"[оголошення, реєстрація, лист, запис, продажна сторінка, оплата, доступ, вилучити фальшивий чат і платіж за шаблон, власник доступу повторює тариф]","decision":"послідовний маршрут","evidence":"умови до платежу","nextStep":"новий тестовий запис і потрібний тариф","wrongAnswer":"Визнати маршрут готовим за квитанцією."}]},"3.5.4":{"prompt":"**INFO-04 · Модератор.** Вигадана школа презентацій продає курс зі зразком слайдів і однією перевіркою. Для кожної картки обери «пропустити» або «відхилити» та назви причину. Пропуск означає проходження перевірок цієї вправи.\n\n| № | Картка |\n|---|---|\n| 1 | «Збери один слайд», у програмі є вправа і приклад |\n| 2 | «Гарантовано заробиш $1 000», доказу немає |\n\n| № | Картка |\n|---|---|\n| 3 | «Одна перевірка», вона входить до показаного тарифу |\n| 4 | Та сама фраза, перевірка є лише в іншому тарифі |\n| 5 | Навчальні числа явно позначено на демо |\n| 6 | «Ти в боргах і не вмієш заробляти» |\n| 7 | Учнівську роботу показано з дозволом і контекстом |\n| 8 | Вигадане свідчення подано як справжнє |\n| 9 | Повна ціна й графік внесків видимі до платежу |\n| 10 | Один внесок названо повною ціною |","exercises":[{"id":"INFO-04","types":["Модератор"],"states":"[десять карток, фактичний перелік можливостей]","input":"[swipe: пропустити або відхилити, choice: причина, text: різниця 3 і 4]","answer":"[1 так, 2 ні, 3 так, 4 ні, 5 так, 6 ні, 7 так, 8 ні, 9 так, 10 ні]","decision":"десять свайпів","evidence":"програма або фактичні умови","nextStep":"виправити обіцянку та повторити контроль","wrongAnswer":"Пропустити 4, бо школа має перевірку в іншому пакеті."}]},"3.5.5":{"prompt":"**INFO-05 · Діагноз.** У вигаданої школи пакет $72, виплата $15 після повної оплати. Замовлення C-42 має два успішні внески по $24. Третій відхилено. У звіті два записи «продаж», остаточного зарахування немає. Обери причину: два окремі курси, помилковий облік внесків як продажів або втрата явки. Назви першу перевірку й доказ повтору.","exercises":[{"id":"INFO-05","types":["Діагноз"],"states":"[одне замовлення, три транзакції, два записи продажу]","input":"[choice: діагноз, text: контроль і доказ повтору]","answer":"[внески помилково пораховано як продажі, зіставити ID й статуси, 48 фактично сплачено і 0 зарахувань]","decision":"одне неповністю сплачене замовлення","evidence":"два успішні внески і одна відмова","nextStep":"перевірити повтор із повною оплатою","wrongAnswer":"Нарахувати 30 доларів за два записи."}]},"3.5.6":{"prompt":"**INFO-06 · Знайди блокер.** Польський продавець електронної книги посилається на виняток після негайної видачі. Торкнися рядка, де бракує доказу.\n\n| Рядок | Факт |\n|---|---|\n| 1 | Повну ціну видно до оплати |\n\n| Рядок | Факт |\n|---|---|\n| 2 | Файл видано одразу, окремого доказу попередньої згоди та підтвердження наслідків немає |\n| 3 | Створено квитанцію |\n| 4 | Адресу підтримки опубліковано |","exercises":[{"id":"INFO-06","types":["Знайди блокер"],"states":"[чотири рядки, заявлений виняток]","input":"[tap_row: 1–4, text: потрібний доказ]","answer":"[2, попередня явна згода і підтвердження наслідків та договору]","decision":"виняток не прийнято","evidence":"немає потрібного запису","nextStep":"виправити і повторити чекаут","wrongAnswer":"Прийняти виняток за наявністю квитанції."}]},"3.5.F":{"prompt":"**INFO-07 · Воронка + Журнал + Порахуй.** Тест Meta у Польщі. Обери офер і відкривай три зрізи по черзі.\n\n| Поле | A. Slajd po Slajdzie | B. Szybki Dochód |\n|---|---|---|\n| Продукт | Курс презентацій, дві практичні роботи з однією перевіркою | Курс із гарантією заробітку та винагородою переважно за залучення нових учасників |\n| Ціна | $80 (≈320 PLN, покупець платить у злотих), разово або два внески по $40 | $100, структура продукту й виплат непрозора |\n| Договірна дія | $16 за повністю сплачене й зараховане замовлення, після перевірки повернень | $22 за запис, визначення не надано |\n| Календар і джерело | 14 днів перевірки після повної оплати, 14 днів холду від зарахування, капа 8 за добу за Варшавою, Meta письмово дозволено мережею | Канал і строки не підтверджено |\n\nВибери A або B. Запропонуй кут з однією навичкою і одним доказом у програмі. Розклади оголошення, реєстрацію, лист з файлом, вебінар, чекаут і доступ. Підпиши, де покупець бачить загальну ціну та перший внесок. Окремо назви, як перевіриш час польського ефіру й підставу для подальшого рекламного повідомлення.\n\n### Зріз 1. Передзапускові блокери\n\n| Крок | Очікування | Факт |\n|---|---|---|\n| Лист і ефір | Той самий локальний час | Час збігається |\n| Перший внесок | Один платіж, ще без нового зарахованого продажу | Подія назвала внесок остаточним продажем |\n| Доступ | Тариф із перевіркою роботи | Відкрився пакет без перевірки |\n| Чекаут | Видимі загальна ціна, графік і умови | У тесті показані |\n\nЗапиши два блокери, власників і докази повтору. Потім відкрий підтверджений повтор: власник вимірювання відділив внесок від остаточного статусу, власник платформи правильно видав пакет з перевіркою. У повторі збережено одну транзакцію за внеском. Негативний тест з відхиленою оплатою не видає платний доступ. Інші перевірки паперового кейсу закриті.\n\n### Зріз 2. Ранній звіт\n\nЄ 60 прийнятих реєстрацій, 30 учасників, 8 початків оплати і 3 зараховані продажі. Реклама $70, супутні витрати $12, усе сплачено до переказу. Порахуй явку від прийнятих, частку початків оплати від учасників, нарахування та касову потребу. Відклади остаточний висновок до дозрівання.\n\n### Зріз 3. Зрілий звіт\n\nТі самі 60 реєстрацій дали 6 зарахованих продажів після одного повернення серед повністю оплачених. Порахуй остаточне нарахування, результат, дохід баєра на реєстрацію, фактичний CPL та граничний CPL. Для нового дня вже зараховано шість дій, ще дві можуть зарахуватися до скидання. Визнач залишок і прийми рішення про збільшення спенду.\n\n### Захисти рішення у трьох реченнях\n\nУ першому назви обраний продукт і його доказ. У другому поясни, що змінилося між раннім і зрілим зрізом. У третьому назви, коли повториш перевірку капи і хто підтвердить доступну касу. Якщо менеджер повідомляє про запланований переказ, попроси фактичний платіжний доказ. Масштабування починай тільки після звірки обсягу, грошей і здатності школи надати обіцяний доступ.","exercises":[{"id":"INFO-07","types":["Воронка","Журнал","Порахуй"],"states":"[дві картки, журнал блокерів, повтор, ранній звіт, зрілий звіт і капа]","input":"[choice: офер, order: маршрут, journal: два блокери і повтор, number: ранні та зрілі показники, text: рішення]","answer":"[A, статус внеску і помилковий тариф, 50%, 26.67%, 48, 82, 96, 14, 1.60, 1.1667, 1.40, 0, відкласти масштабування]","decision":"A і два підтвердження до витрат","evidence":"зрілі продажі й підписані знаменники","nextStep":"звірити капу та переказ","wrongAnswer":"Помножити вісім початків оплат на 16 доларів."}]},"3.6.1":{"prompt":"**MOB-01 · Оціни офер.** Потрібен тест Meta для Android у Чехії. A: головоломка має доступну сторінку, ставка $4 за прийнятий вступ, канал дозволено. B: утиліта доступна лише на iOS, ставка $6 за перший запуск. C: утиліта має Android-сторінку, але канал дозволено лише для пошуку. Вибери офер до підготовки, поясни два блокери і назви доказ до витрат.","exercises":[{"id":"MOB-01","types":["Оціни офер"],"states":"[три картки, бриф Meta Android Чехія]","input":"[choice: офер, text: два блокери і контроль]","answer":"[A, B інша ОС, C інший канал]","decision":"A до підготовки","evidence":"локальна сторінка і письмове джерело","nextStep":"тестовий вступ і зарахування","wrongAnswer":"B через ставку. Бриф вимагає Android."}]},"3.6.2":{"prompt":"**MOB-02 · Порахуй.** У вигаданій грі набір рівнів коштує $16, ставка $4 за прийнятий вступ. Є 80 перших запусків, 32 активні D1, 12 активні D7 і 20 прийнятих вступів. Реклама $60, супутні $12. Порахуй CPI, два показники утримання, повну вартість зарахування, межу CPI та результат. Що зміниться, якщо три дії сторнують?","exercises":[{"id":"MOB-02","types":["Порахуй"],"states":"[закрита група, витрати й ставка, окреме коригування]","input":"[number: CPI і D1 та D7, number: повна ціна дії та межа CPI і результат, number: результат після коригування]","answer":"[0.75, 40%, 15%, 3.60, 0.85, 8, -4]","decision":"застосувати ставку до прийнятих дій","evidence":"відрізнити знаменники та витрати","nextStep":"звірити сторнування","wrongAnswer":"Помножити всі 80 встановлень на ставку за вступ."}]},"3.6.3":{"prompt":"**MOB-03 · Воронка.** Вигадана чеська Android-гра платить за перший завершений вступ. Розклади картки «оголошення», «промосторінка з позначеним демо», «Google Play», «перший запуск», «вступ», «зарахування». Вилучи «завершення браузерного демо як оплачуваний вступ». Назви контроль для користувача, який відкрив посилання на iOS.","exercises":[{"id":"MOB-03","types":["Воронка"],"states":"[бриф Android Чехія, сім карток]","input":"[order: шість кроків, select: зайва картка, text: негативний контроль]","answer":"[оголошення, демо, Google Play, перший запуск, вступ, зарахування, відкинути оплату за демо]","decision":"магазин і фактичний вступ перед зарахуванням","evidence":"браузерний та Android-шляхи розрізнено","nextStep":"контроль іншої ОС без зарахування","wrongAnswer":"Зарахувати завершення демо замість вступу."}]},"3.6.4":{"prompt":"**MOB-04 · Модератор.** Вигадана Android-головоломка має одиночний вступ і додаткові платні рівні. Для кожної картки обери «пропустити» або «відхилити» та поясни причину. Пропуск означає проходження перевірки цієї вправи.\n\n| № | Картка |\n|---|---|\n| 1 | Запис фактичного першого рівня |\n\n| № | Картка |\n|---|---|\n| 2 | Ролик обіцяє мережеву гру, її немає |\n| 3 | Демо позначено, в ньому той самий поворот |\n| 4 | Демо обіцяє режим, якого немає в застосунку |\n| 5 | Додатковий рівень із видимою платною умовою |\n| 6 | Той самий рівень подано як безоплатний |\n| 7 | Запис показує справжню реакцію на неправильний хід |\n| 8 | Кнопка відкриває іншу гру |\n| 9 | Магазин і версія відповідають ролику |\n| 10 | Замість ходу жест одразу відкриває магазин |\n\n**MOB-09 · Діалог.** Редактор просить погодити ролик зі вступом на платному рівні. У поточній збірці цей рівень відкривається після покупки. Напиши три речення, які описують рішення, доказ і перевірку нової версії.","exercises":[{"id":"MOB-04","types":["Модератор"],"states":"[десять карток, опис фактичної гри]","input":"[swipe: пропустити або відхилити, choice: причина, text: різниця карток 5 і 6]","answer":"[1 так, 2 ні, 3 так, 4 ні, 5 так, 6 ні, 7 так, 8 ні, 9 так, 10 ні]","decision":"десять свайпів","evidence":"фактична дія і версія або розбіжність","nextStep":"виправити матеріал і повторити маршрут","wrongAnswer":"Пропустити 6, бо рівень існує. Платна умова прихована."},{"id":"MOB-09","types":["Діалог"],"states":"[ролик і контрольний прохід]","input":"[text: три речення]","answer":"[повернути ролик, послатися на купівлю, повторити прохід]","decision":"зупинити поточний ролик","evidence":"рівень поза вступом","nextStep":"показати фактичний вступ і повторити контроль","wrongAnswer":"Пропустити після заміни заголовка без перевірки кадрів."}]},"3.6.5":{"prompt":"**MOB-05 · Діагноз.** У вигаданій Android-грі QA-61 відкрив застосунок і завершив вступ. У журналі гри видно обидві події. Тестовий звіт MMP містить тільки перший запуск і погоджений строк очікування вже минув. Обери причину: немає запуску, немає доказу передачі вступу або завершено виплату. Назви перший контроль і доказ повтору.","exercises":[{"id":"MOB-05","types":["Діагноз"],"states":"[журнал гри, звіт MMP і строк]","input":"[choice: причина, text: контроль і доказ]","answer":"[немає доказу передачі вступу, звірити карту та реліз, один новий вступ з очікуваним статусом]","decision":"знайти останній підтверджений етап","evidence":"вступ є тільки у грі","nextStep":"повторити тест із новим ключем","wrongAnswer":"Замінити вступ на перший запуск у фінальному реєстрі."}]},"3.6.6":{"prompt":"**MOB-06 · Знайди блокер.** Для вигаданої Android-гри торкнися рядка, де розходяться умови покупки.\n\n| Рядок | Факт |\n|---|---|\n| 1 | Картка та реліз відповідають країні |\n| 2 | Ролик обіцяє повний доступ без оплати, але перед другим рівнем вимагають підписку |\n| 3 | Назва видавця збігається |\n\n| Рядок | Факт |\n|---|---|\n| 4 | Вступ зараховується один раз |\n\nНазви правку й контроль, який має пройти після неї.","exercises":[{"id":"MOB-06","types":["Знайди блокер"],"states":"[чотири контрольні рядки]","input":"[tap_row: 1–4, text: правка і доказ]","answer":"[2, описати фактичний безоплатний обсяг і платну умову, повторити чекаут]","decision":"рядок 2","evidence":"обіцянка суперечить оплаті","nextStep":"звірити реліз і умови до зобов’язання","wrongAnswer":"Рядок 4. Одне зарахування не підтверджує умови оплати."}]},"3.6.7":{"prompt":"**MOB-07 · День за днем.** Вигадана гра платить $4 за прийнятий вступ. День 1: витрачено $15, перших запусків немає, погоджений поріг $15. День 2: маршрут виправили, у попередній зрілій групі 18 прийнятих вступів і $65 витрат. День 3: партнерка відхилила ще три вступи за кодом повтору. Капа 20, уже зараховано 17 інших дій, ще три відкриті. Назви дію, підсумки до й після коригування та залишок капи.","exercises":[{"id":"MOB-07","types":["День за днем"],"states":"[три послідовні зрізи]","input":"[choice: перша дія, number: два результати і капа, text: контроль]","answer":"[пауза і звірка маршруту, 7, -5, 0, перевірити три коригування й капу після скидання]","decision":"відкласти обсяг","evidence":"прийняті дії після коригування і зайнята капа","nextStep":"звірка джерела й нового залишку","wrongAnswer":"Масштабувати за початковим плюсом."}]},"3.6.F":{"prompt":"**MOB-08 · Воронка + Журнал + Порахуй.** Мета — один тест Meta Ads для Android у Чехії. Відкривай зрізи по черзі.\n\n| Поле | A. Bloky Doma | B. Skládej Spolu |\n|---|---|---|\n| Продукт | Головоломка, Android, Чехія; безоплатний вступ, додаткові рівні $20 (≈460 CZK) | Головоломка лише на iOS, рівні $22 (≈506 CZK) |\n| Виплата | $6 за перше зараховане завершення вступу до семи днів від першого запуску | $7 за прийнятий перший запуск |\n| Умови | Meta дозволено мережею, капа 20 дій на добу за Прагою, холд 14 днів від зарахування | Джерело не підтверджено |\n| Дублі | Повтор того самого гравця не оплачується | Правило не надано |\n\nВибери офер. Розклади картки «оголошення», «магазин», «перший запуск», «вступ», «фінальний реєстр». Запропонуй кадр із підтвердженим правилом гри. Вкажи, що перевіриш у мобільному перегляді та у фактичній збірці.\n\n### Зріз 1. Два блокери перед спендом\n\n| Крок | Очікування | Факт |\n|---|---|---|\n| Кнопка | Правильна Android-версія для Чехії | Відкривається картка іншого релізу |\n| Вступ | Окрема договірна подія | У грі вступ завершено, у MMP видно тільки перший запуск після завершення строку звірки |\n| Оплата | Вступ без покупки | Тест підтвердив |\n| Рекламний кут | Показана дія доступна | Поворот блоку відтворено |\n\nНазви власників й ознаки виправлення. Після відповіді відкрий повтор: редактор маршруту показав потрібну картку; інтегратор провів новий контроль, у якому видно завершення вступу в грі та MMP і один тестовий фінальний запис. Негативний прохід без завершення вступу не створив зарахування. Інші перевірки паперового кейсу закриті.\n\nПідпиши час та ідентифікатор контрольного проходу. Для підтримки достатньо синтетичного запису, ОС та версії. Не додавай чужий обліковий запис або приватні дані. Якщо після правки видно тільки звіт MMP, поверни останній крок партнеру для підтвердження. Технічна подія й договірний статус можуть надійти в різний час.\n\n### Зріз 2. Ранній звіт\n\nРеклама $78, супутні витрати $12. Когорта має 60 атрибутованих перших запусків, 24 активних D1. Поки є 10 зарахувань, частина статусів відкриті. Порахуй фактичний CPI, D1 і проміжне нарахування. Визнач касову потребу до виплати. Підпиши день витрат, день зарахування й дату фактичного переказу окремо.\n\n### Зріз 3. Зрілий звіт\n\nСеред тих самих 60 запусків на D7 активні 12, вступ завершили 20, зарахували 16. Порахуй D7, конверсію у вступ, частку зарахованих дій від запусків, повну вартість зарахованої дії та результат. Для нового дня є 16 уже зарахованих і ще чотири можливих до скидання. Чи можна збільшити обсяг?\n\n### Захисти висновок\n\nНазви, з чим збігаються два записи в позитивному тесті. Якщо адреса веде не туди, покажи фактичний перехід з реклами. Якщо подія зникла в MMP, зафіксуй час і версію та звернись до власника інтеграції. У фінансовому висновку поясни, чому +$6 не дають права збільшити сьогоднішній обсяг. Запропонуй дату перевірки капи й доступної каси. Для нового GEO або ОС повтори перевірку магазину і договірної дії окремо.","exercises":[{"id":"MOB-08","types":["Воронка","Журнал","Порахуй"],"states":"[дві картки, блокери, повтор, ранній звіт, зрілий звіт і капа]","input":"[choice: офер, order: маршрут, journal: два блокери, number: ранні і зрілі показники, text: рішення]","answer":"[A, неправильний реліз і відсутня подія, 1.30, 40%, 60, 90, 20%, 33.33%, 26.67%, 5.625, 6, 0, відкласти]","decision":"A і два докази перед витратами","evidence":"підписані бази і зрілий статус","nextStep":"звірити капу та касу","wrongAnswer":"Зарахувати двадцять внутрішніх подій за ставкою 6 доларів."}]},"3.7.1":{"prompt":"**BET-01 · Оціни офер.** A: умовний запис для ставок збігається з оператором і доменом, але афіліат ще не має підтвердження для каналу. B: казино показує запис лише для ставок. C: соціальна гра не пояснює обмін платних жетонів. Запиши три рішення й доказ до кожного.","exercises":[{"id":"BET-01","types":["Оціни офер"],"states":"[три картки і умовні докази]","input":"[choice: рішення за кожною, text: відкриті докази]","answer":"[A пауза до допуску, B відхилити поточний маршрут, C класифікувати]","decision":"окремі стани","evidence":"канал і вид діяльності та механіка","nextStep":"запит точного документа","wrongAnswer":"Запустити A за записом ліцензії."}]},"3.7.2":{"prompt":"**BET-02 · Порахуй.** Вигадана CPA-картка платить $25 за кінцеву дію: шість FTD, чотири зараховано, один відкритий, один відхилено. В окремій угоді RevShare 20%, від’ємна база першого місяця −$50, другого +$200. Порахуй поточну CPA, а для RevShare — комісію другого місяця з перенесенням і без нього. Назви договірний доказ.","exercises":[{"id":"BET-02","types":["Порахуй"],"states":"[дві незалежні картки, відкритий CPA і два варіанти перенесення]","input":"[number: CPA, number: два RevShare, text: доказ]","answer":"[100, 30, 40, рядок прийняття та правило перенесення бази]","decision":"розрахувати моделі окремо","evidence":"чотири зарахування та база 150 або 200","nextStep":"звірити правило і фінальний статус","wrongAnswer":"Нарахувати 150 за всі шість FTD."}]},"3.7.3":{"prompt":"**BET-03 · Порахуй.** Вигадана група має 80 кліків, 16 реєстрацій і шість FTD на суму $150. Чотири дії зараховано по $25, витрати $90. Окрема модель дає 20% від накопиченої бази $300 на третьому місяці і $550 на шостому. Порахуй частки, середній депозит, два фінансові сценарії та рішення, якщо витрати ще не покрито переказом.","exercises":[{"id":"BET-03","types":["Порахуй"],"states":"[закрита група CPA і окрема накопичена база RevShare]","input":"[number: частка реєстрацій і FTD та середній депозит, number: три фінансові результати, text: потрібний доказ]","answer":"[20%, 37.5%, 25, 10, -30, 20, фактичний переказ]","decision":"порівняти угоди окремо","evidence":"правильні знаменники і витрати","nextStep":"звірити реєстр і доступну касу","wrongAnswer":"Множити всі шість депозитів на ставку."}]},"3.7.4":{"prompt":"**BET-04 · Воронка.** Для вигаданої пропозиції ставок упорядкуй картки: оголошення, підписаний преленд, сайт оператора, реєстрація, перевірка особи й віку, перевірка обмежень участі, умовний депозит, фінальний статус. Вилучи картку «перейти до фінансування за відкритого KYC». Назви, що має показати негативний тест.","exercises":[{"id":"BET-04","types":["Воронка"],"states":"[паперовий бриф і дев’ять карток]","input":"[order: маршрут, select: зайва картка, text: негативний доказ]","answer":"[оголошення, преленд, оператор, реєстрація, перевірка, обмеження, умовний депозит, статус, вилучити обхід]","decision":"захисні кроки перед фінансуванням у кейсі","evidence":"блокування при відкритій перевірці","nextStep":"повторити негативний і позитивний проходи","wrongAnswer":"Поставити депозит до завершення перевірки."}]},"3.7.5":{"prompt":"**BET-05 · Модератор.** Для кожної картки вкажи рішення, доказ і наступний крок. Варіанти — відхилити версію, повернути на виправлення або по докази, передати на фінальну перевірку.\n\n| Картка | Що є в досьє |\n|---|---|\n| A | Фактична картка «Табло», усі потрібні докази первинної перевірки. |\n| B | «Коло» гарантує виграш у першому кадрі. |\n| C | У стримі відома особа просуває оператора з промокодом. |\n| D | Оплачений матеріал про виграш замасковано під репортаж, є кнопка гри. |\n| E | Позначка «21+» є, доказ налаштування аудиторії відсутній. |\n\n| Картка | Що є в досьє |\n|---|---|\n| F | У телефонному перегляді кнопку накладено на застереження. |\n| G | Картка букмекера відкриває сайт іншого оператора казино. |\n| H | Є чинна ліцензія, в досьє відсутня підстава для запланованого показу. |","exercises":[{"id":"BET-05","types":["Модератор"],"states":"[вісім паперових карток]","input":"[select: рішення, text: доказ, text: наступний крок]","answer":"[A передати, B відхилити, C відхилити, D відхилити, E повернути, F повернути, G відхилити, H повернути]","decision":"пройти кожну картку","evidence":"вказати фактичний блокер","nextStep":"назвати власника або повторний тест","wrongAnswer":"Пропустити E лише через напис 21+."}]},"3.7.6":{"prompt":"**BET-06 · Діагноз.** У «Табло» R-01 дав два повідомлення FTD з тим самим ID та одне підтверджене зарахування. У R-02 депозит $19 і фінальна відмова. У R-03 є REG і відкритий статус партнера. У «Колі» серпень закритий, а вересень попередній. Надай фінансовий підсумок, визнач рядок повторної звірки та запиши, за якої умови QUAL можна залишити в паперовому плані.","exercises":[{"id":"BET-06","types":["Діагноз"],"states":"[синтетичні журнали двох треків]","input":"[number: виплата Табло, select: рядок повторної звірки, text: період Кола і умова для QUAL]","answer":"[30 USD, R-03 після закриття, серпень, дозвіл і перевірена доставка QUAL]","decision":"одна оплачувана дія","evidence":"однаковий ID і закритий реєстр","nextStep":"повторити звірку R-03 і перевірити QUAL","wrongAnswer":"Нарахувати $60 через два повідомлення FTD для R-01."}]},"3.7.7":{"prompt":"**BET-07 · Знайди блокер.** Познач перший блокер у кожному рядку журналу. U-1 має ліцензію, але для показу в Україні немає підстави за ст. 22-1. P-1 має польський дозвіл на ставки, а кнопка відкриває казино. R-1 містить тільки ліцензію класу II постачальника. Для кожного випадку запиши, хто має надати доказ або виправити розбіжність.\n\n**BET-09 · Діалог.** Менеджер пише: «Оператор той самий, змінився лише домен. Старих документів вистачить». У паперовому досьє немає підтвердження для нової адреси. Напиши три речення: рішення, потрібний доказ і перевірку після відповіді.","exercises":[{"id":"BET-07","types":["Знайди блокер"],"states":"[паперовий журнал трьох GEO]","input":"[select: проблемне поле в кожному рядку, text: відповідальний і доказ]","answer":"[U-1 підстава показу, P-1 фактичний маршрут, R-1 дозвіл оператора]","decision":"зупинити три рядки","evidence":"знайти конкретне непідтверджене поле","nextStep":"повернути власнику підстави або маршруту","wrongAnswer":"Пропустити P-1 через наявність польського дозволу."},{"id":"BET-09","types":["Діалог"],"states":"[чат і два маршрути]","input":"[text: три речення]","answer":"[пауза, підтвердження нової адреси, повтор правового та платформного контролю]","decision":"зупинити нову версію","evidence":"старе досьє не містить нової адреси","nextStep":"звірити документ і фактичний маршрут","wrongAnswer":"Погодити нову адресу за словами менеджера."}]},"3.7.8":{"prompt":"**BET-08 · День за днем.** День 1: «Коло» дає попередню базу $360, ставку 25% і витрати $70. День 2: із бази вилучено $100, звіт закрито, переказу ще немає. День 3: у макеті профіль із самообмеженням бачить активну кнопку продовження. Запиши нарахування, різницю після витрат, стан каси та рішення з наступним кроком.","exercises":[{"id":"BET-08","types":["День за днем"],"states":"[попередній звіт, закритий звіт, контроль захисту]","input":"[number: нарахування, number: різниця, text: стан каси, select: рішення, text: доказ і наступний крок]","answer":"[65 USD, -5 USD, переказу немає, стоп, зафіксувати збій і повторити контроль]","decision":"зупинити тест","evidence":"формула і активна кнопка","nextStep":"передати відповідальному та повторити негативний прохід","wrongAnswer":"Продовжити, бо попередній розрахунок давав +$20."}]},"3.7.F":{"prompt":"**BET-F · Воронка + Журнал + Порахуй.** Проведи обидва треки від картки до рішення, використовуючи факти з таблиці. Не додавай вигаданих дозволів. Заповни рядки так, щоб можна було повторити розрахунок без усних пояснень.\n\n| Матеріал | «Табло» | «Коло» |\n|---|---|---|\n| Картка | CPA $30 за фінально зараховану дію. Baseline включає перший депозит від $20, завершені перевірки та відсутність дубля. | RevShare 25% від бази після договірних коригувань. |\n| Досьє | Оператор і кінцевий продукт збігаються. Доказу авторизації майданчика для заявленого показу немає. | Оператор і кінцевий продукт збігаються. Контрольний кадр K-12 показує активну кнопку за чинного самообмеження. |\n| Ранній зріз | 18 REG, 6 унікальних FTD, витрати $75. | Попередня база $440, витрати $85. |\n| Зрілий зріз | Закритий реєстр: три зарахування, два записи нижче порогу, один підтверджений дубль облікового запису. Переказу немає. | База в закритому звіті $320. Рядок −$120 вже враховано. Переказу немає. |\n\n1. Намалюй маршрут «Табло» від оголошення до кінцевого статусу й покажи, де перевірка особи, віку та обмежень має зупинити учасника. Для «Кола» покажи, де в протоколі відокремлюєш контроль захисту від закриття фінансового звіту.\n\n2. Визнач ранній індикатор для кожного треку. Для «Табло» порахуй частку FTD серед REG. Для «Кола» порахуй попереднє нарахування й підпиши його статус.\n\n3. Порахуй зріле нарахування, різницю після витрат і стан каси для обох треків. Для «Кола» покажи, як попередня база перейшла до закритої. Для «Табло» запиши три причини розподілу шести депозитів за фінальними статусами.\n\n4. Знайди два незалежні блокери. Для кожного внеси у журнал доказ, відповідального й умову повторної перевірки. Напиши по три речення для фінального висновку: рішення, доказ, наступний крок.\n\n### Підготуй висновок для передачі\n\nСклади перше речення з дієслова: «зупиняю», «повертаю» або «передаю на фінальну перевірку». Воно має називати обсяг рішення. Наприклад, «повертаю фінансовий рядок на звірку» залишає інші частини протоколу окремими. У другому реченні вкажи версію, суму або точний рядок, який обґрунтовує рішення. У третьому назви власника дії та перевірку, після якої рішення можна переглянути. Капа обмежує обсяг дій за умовами офера. Навіть якщо капа вільна і зрілий зріз позитивний, масштабування лишається закритим, поки не усунуто блокер і не підтверджено касу.\n\nПеред здачею прочитай таблицю від кінця до початку. Перевір, чи кожне рішення посилається на факт, а кожен факт має версію. Якщо витрати віднято двічі або попередню базу помилково додано до закритої, повернись до рядка формули. Якщо висновок пропонує публікацію, а в журналі ще є блокер, виправ рішення. Підпиши, що перевірено на паперових матеріалах.\n\n### Перевір, що інший читач відтворить результат\n\nПодивись на ранній зріз так, ніби закритого реєстру ще немає. Для «Табло» порахуй, скільки записів перейшло від реєстрації до депозиту, і залиш поле остаточної виплати відкритим. Поруч запиши, який документ його закриє. Для «Кола» запиши прогноз із датою та окремий рядок для остаточного нарахування. Після відкриття зрілого зрізу збережи ранні рядки. Це дасть змогу відновити хід рішення й перевірити, чи висновок про результат спирався на дані, доступні на той момент.\n\nПрочитай запис, у якому написано «грошей немає». Уточни, про що йдеться: відсутнє нарахування або ще не було переказу. Для цього залиш окремі поля «нараховано», «надійшло» і «витрачено». У касовому висновку покажи, скільки вже витрачено за кожним кейсом. У фінансовому підсумку використай нарахування з відповідного звіту.\n\nНарешті уяви, що відповідальний надіслав нову версію тільки для одного треку. У журналі познач її дату, відкрий пов’язаний блокер і повтори потрібний контроль. Збережи рішення по другому треку разом з його старою версією та доказом. Так нова відповідь про авторизацію не загубить відкритий\n\nзбій захисту.\n\n### Типова помилка\n\n**Типова помилка в навчальній ситуації.** Звести обидва кейси в одну суму і дати їм спільне рішення. Залиши окремі підсумки та докази, бо договори й блокери різні.","exercises":[{"id":"BET-F","types":["Воронка","Журнал","Порахуй"],"states":"[дві картки, ранній зріз, зрілий реєстр, два блокери]","input":"[order: маршрут, number: нарахування і результат, text: журнал і висновки]","answer":"[Табло 33.3% і $90 та +$15, Коло $110 попередньо і $80 та -$5 зріло, переказу немає, два стопи]","decision":"окреме рішення для кожного треку","evidence":"формули й докази двох блокерів","nextStep":"авторизація і негативний повторний прохід","wrongAnswer":"Дозволити показ Табло через додатний результат."}]},"3.8.1":{"prompt":"**FIN-01 · Оціни офер.** У FIN-21 анкета прийнята, видано позику. У FIN-22 анкету прийнято, видача відкрита. У CRY-21 верифікований новий запис має перший зарахований депозит $31 на шостий день. У CRY-22 депозит $29 на п’ятий день. Усі записи унікальні, зазначені кінцеві статуси підтверджені партнером. Порахуй нарахування FIN-A в кожній окремій моделі й нарахування CRY-B. Запиши, у якому записі та що потрібно повторно звірити.","exercises":[{"id":"FIN-01","types":["Оціни офер"],"states":"[дві картки й чотири записи]","input":"[number: CPL, number: CPA позики, number: CPA криптобіржі, text: доказ і повторна звірка]","answer":"[12 USD, 30 USD, 24 USD, FIN-22 після закриття]","decision":"розділити моделі","evidence":"статуси поріг і строк","nextStep":"звірити видачу FIN-22","wrongAnswer":"Нарахувати обидві фінансові ставки за один запис."}]},"3.8.2":{"prompt":"**FIN-02 · Порахуй + Діагноз.** Група FIN-A має 30 подань, п’ять повторів і одну неповну анкету. На першому зрізі є одна видача й 12 заявок очікують рішення. Після закриття із прийнятих анкет дев’ять схвалено й чотири видано, усі чотири зараховано. Витрати $120, переказу немає. Порахуй частку схвалень, результати двох альтернативних договорів і касовий стан. Визнач, чому одна рання видача дає хибний остаточний висновок, і назви документ для звірки CPA.","exercises":[{"id":"FIN-02","types":["Порахуй","Діагноз"],"states":"[ранній і закритий зріз однієї групи]","input":"[number: частка схвалень, number: результат CPL, number: результат CPA, text: каса й доказ]","answer":"[37.5%, 24 USD, 0 USD, каса -120 USD, закритий реєстр видач і зарахувань]","decision":"оцінити закриту групу окремо за договорами","evidence":"24 прийняті і 4 зараховані","nextStep":"звірити переказ після холду","wrongAnswer":"Оцінити CPA остаточно за однією ранньою видачею."}]},"3.8.3":{"prompt":"**FIN-03 · Воронка.** Для прямої форми розклади картки «креатив», «офіційний лендинг», «інформація про отримувача й мету», «подання», «реєстр». Для сайту порівняння знайди дві проблеми: форма Meta запитує дохід, а додаткова копія анкети йде невказаному брокеру. У журналі FIN-A два повідомлення про одну анкету, партнер прийняв її, видача відкрита. Покажи, що запишеш для CPL і CPA.\n\n**FIN-07 · Діалог.** Менеджер пише: «Додай загальну згоду, брокера в описі можна не згадувати. Трекеру лиши дохід для звірки». У макеті підтверджено лише кредитора, а технічному журналу досить ключа й статусу. Напиши три речення з рішенням, потрібним доказом і повторною перевіркою.","exercises":[{"id":"FIN-03","types":["Воронка"],"states":"[два паперові маршрути, два блокери, технічний журнал]","input":"[order: прямий маршрут, select: проблемні вузли, text: статуси CPL і CPA]","answer":"[креатив лендинг інформація подання реєстр, дохід і невказаний брокер, CPL 6 USD CPA очікує]","decision":"зупинити проблемну форму і передачу","evidence":"поля і фактична схема плюс партнерський статус","nextStep":"виправити маршрут і повторити синтетичний прохід","wrongAnswer":"Вважати два повідомлення двома анкетами або додати один загальний прапорець і залишити невказаного брокера."},{"id":"FIN-07","types":["Діалог"],"states":"[повідомлення менеджера, форма та схема]","input":"[text: три речення]","answer":"[зупинити передавання, звірити отримувачів та поля, повторити синтетичний прохід]","decision":"поставити маршрут на паузу","evidence":"сторонній отримувач і зайве поле","nextStep":"звірити схему та записи після виправлення","wrongAnswer":"Додати загальну згоду і зберегти той самий маршрут."}]},"3.8.4":{"prompt":"**FIN-04 · Модератор.** Вибери для кожної картки рішення: відхилити, повернути по доказ або правку, передати на фінальну перевірку. Укажи конкретний доказ і наступну дію.\n\n| Картка | Чернетка |\n|---|---|\n| A | «A дешевша», видно тільки $10 процентів і $12 у конкурента. |\n\n| Картка | Чернетка |\n|---|---|\n| B | «Поверни $110», договір A містить ще $5 комісії. |\n| C | Порівняння $115 і $112 за однакових умов, документ і читабельний перегляд додано. |\n| D | На мобільному обрізано строк, хоча в джерелі він є. |\n| E | «Гарантований дохід після відкриття рахунку». |\n| F | Згенероване відео вигадує рекомендацію відомої особи. |\n| G | Справжня цитата про інший продукт подана як підтримка цього. |\n| H | Нейтральна картка біржі, але сторінку тарифу неможливо звірити. |","exercises":[{"id":"FIN-04","types":["Модератор"],"states":"[вісім карток і два джерела умов]","input":"[select: рішення, text: доказ і наступний крок]","answer":"[A відхилити, B відхилити, C передати, D повернути, E відхилити, F відхилити, G відхилити, H повернути]","decision":"класифікувати всі картки","evidence":"навести фразу кадр або документ","nextStep":"передати відповідальному чи повторити контроль","wrongAnswer":"Пропустити A бо 10 менше за 12."}]},"3.8.5":{"prompt":"**FIN-05 · Знайди блокер.** У рядку F1 є витяг власника преленду, а право кредитора на видачу не підтверджено. У C1 є старий запис про місцеву реєстрацію біржі, без чинної підстави за MiCA. У C2 право на послугу підтверджено, а заявника в дозволі Meta не звірено. Познач відсутнє поле, джерело й відповідального для кожного рядка.","exercises":[{"id":"FIN-05","types":["Знайди блокер"],"states":"[три рядки синтетичного досьє]","input":"[select: блокер, text: джерело і відповідальний]","answer":"[право кредитора, підстава за MiCA, авторизація заявника в Meta]","decision":"залишити три рядки відкритими","evidence":"визначити три відсутні докази","nextStep":"повторити звірку за отриманими документами","wrongAnswer":"Закрити C2 за записом ESMA без доказу допуску реклами."}]},"3.8.6":{"prompt":"**FIN-06 · Оціни офер.** Досьє X-18 містить несправжню новину, вимогу переказати гроші на рахунок, зв’язок якого зі стороною договору не підтверджено, та кол-центр, який продає інвестиції після форми порівняння позик. У X-19 послуга та маршрут збігаються, але запис про актуальне право на послугу відсутній. Дай рішення для обох досьє, наведи три докази для X-18 і назви наступний крок для X-19.","exercises":[{"id":"FIN-06","types":["Оціни офер"],"states":"[два паперові досьє]","input":"[select: рішення X-18 і X-19, text: докази й наступний крок]","answer":"[відхилити X-18, повернути X-19 по доказ, фальшива новина і невідомий отримувач та підміна послуги]","decision":"розрізнити відмову й очікування доказу","evidence":"вказати джерела трьох ознак","nextStep":"отримати чинне підтвердження і звірити маршрут","wrongAnswer":"Запустити X-18 малим обсягом через високу виплату."}]},"3.8.F":{"prompt":"**FIN-F · Воронка + Журнал + Порахуй.** Заповни два журнали й передай по короткому висновку. У всіх рядках маємо зріз за початковою групою. Суми та реєстри вигадані.\n\n| Матеріал | FIN-A «Рівна сума» | CRY-B «Обмінне вікно» |\n|---|---|---|\n| Картка | CPL $6 за прийняту унікальну анкету або альтернативний CPA $30 за зараховану видачу | CPA $24 за нову верифіковану реєстрацію з першим зарахованим депозитом від $30 у межах семи днів |\n| Досьє | Форма F7 називає одного кредитора. Схема F7 веде також до невказаного брокера. | Договір і лендинг описують обмін; у витягу C5 підтверджено лише послугу зберігання. |\n| Ранній зріз | 24 подання, одне зарахування видачі, витрати $100. Розподіл анкет відкритий. | 16 реєстрацій, 8 верифікацій, 2 зарахування, витрати $88. Вікна ще відкриті. |\n\n| Матеріал | FIN-A «Рівна сума» | CRY-B «Обмінне вікно» |\n|---|---|---|\n| Зрілий зріз | 4 повтори, 2 неповні, 18 прийнято, 8 схвалено, 3 видано й зараховано. | 10 верифікацій, 6 перших депозитів серед них. Чотири дії зараховано, один депозит $29 у строк, ще один $34 на восьмий день. |\n| Фактичні перекази | $0 | $0 |\n\n1. Склади маршрут кожного офера. Для FIN-A познач місце, де людина має побачити мету й отримувача даних. Для CRY-B розділи верифікацію, депозит і договірне зарахування.\n\n2. Порахуй раннє нарахування за CPA для обох кейсів і назви відсутній ранній доказ для CPL. Потім порахуй зріле нарахування, різницю після витрат і касовий результат для кожного треку.\n\n3. Поясни арифметику відсіву. Для FIN-A покажи, скільки з 24 подань прийнято і яка частка прийнятих отримала схвалення. Для CRY-B обґрунтуй обидва нульові рядки серед шести депозитів.\n\n4. Вкажи два незалежні блокери. Зафіксуй версію доказу, рішення щодо показу, відповідального й умову повторної перевірки.\n\n### Перевір роботу перед здачею\n\nДля кожної цифри перевір знаменник, період і тип події. Прочитай окремо висновок про економіку та висновок про допуск: читач має зрозуміти, чому навіть додатний підсумок не закриває невідомого отримувача або непідтверджене право на обмін. Масштабування потребує окремого рішення після закриття блокерів, підтвердження зрілої економіки, звірки капи й фактичної каси. У цій вправі достатньо пояснити, чому до цього етапу не переходять.\n\nУ фінальному журналі лиши слід від раннього висновку до зрілого. Наприклад, у ранньому CPL поле лишається відкритим через незавершену перевірку анкет. Коли з’являється зрілий реєстр, занеси підтверджений розрахунок у новий рядок. Так перевіряльник бачить, що для оновлення підсумку був новий доказ. У рішенні по маршруту запиши, який саме контроль треба повторити, а не загальну фразу «перевірити ще раз».\n\n### Передай рішення з умовою повторної перевірки\n\nОформи кожен висновок у трьох реченнях. У першому назви продукт і рішення щодо показу. У другому вкажи конкретну версію документа й розбіжність. У третьому признач наступну дію. Для кредитного маршруту це може бути контрольний прохід після звірки фактичного передавання. Для криптовалютного — перевірка актуального запису щодо юридичної особи, обміну й країни. Запиши, що саме дозволить переглянути рішення. Якщо виправили лише текст на сторінці, підніми журнал фактичного маршруту та звір, чи змінився відповідний вузол.\n\nДодай короткий фінансовий підсумок до кожного рішення. Вкажи, за якою угодою пораховано суму, чи закрита група й скільки грошей надійшло. Якщо колега переносить підсумок у зведену таблицю, йому має бути зрозуміло, що CPL і CPA для FIN-A є альтернативами. Познач, який зі звітів придатний для планування витрат і чому до підтвердження переказу з нього не можна обчислити доступний залишок усієї команди. За брифом відомі лише витрати й надходження для двох конкретних груп. Цього достатньо, щоб визначити касовий результат кожної групи та записати наступну дату звірки.\n\n### Типова помилка\n\n**Типова помилка в навчальній ситуації.** Порівняти нарахування з переказом за різні групи й випустити матеріал через додатний результат. Звір період і застосуй окремий критерій допуску.","exercises":[{"id":"FIN-F","types":["Воронка","Журнал","Порахуй"],"states":"[два досьє, ранній і зрілий зрізи, два блокери]","input":"[order: маршрути, number: нарахування і результат, text: докази і дії]","answer":"[ранні CPA 30 і 48, зрілі FIN CPL 108 і +8, FIN CPA 90 і -10, CRY CPA 96 і +8, каса -100 і -88, два стопи]","decision":"два окремі блокери","evidence":"зрілі формули і версії F7 та C5","nextStep":"звірити згоду маршрут і право на обмін","wrongAnswer":"Випустити CRY-B через вісім доларів результату."}]},"3.9.1":{"prompt":"**SWP-01 · Порахуй.** У трекері 13 записів. Два не підтверджені, 11 прийнято, три з прийнятих сторновано після чарджбеків. Ставка $12, витрати $100, переказу немає. Порахуй раннє і зріле нарахування, обидва результати після витрат і касовий підсумок. Назви доказ, який покаже, чи три сторно вже включено до кінцевого звіту.\n\n**SWP-05 · Порахуй.** У навчальному квітневому звіті 10 тріалів зараховано по $12, витрати $95. У травні партнер сторнував три квітневі дії. Заробіток за нову травневу групу до віднімання становить $144. Квітневі $120 уже переказано. Порахуй зрілий результат квітневої групи й травневий переказ після коригування.","exercises":[{"id":"SWP-01","types":["Порахуй"],"states":"[ранній реєстр і закриті сторно]","input":"[number: нарахування і результати, text: каса і фінальний доказ]","answer":"[132 USD, 96 USD, +32 USD, -4 USD, -100 USD, остання версія реєстру]","decision":"оцінити зрілу групу","evidence":"11 мінус 3 та версія звіту","nextStep":"звірити статуси й переказ","wrongAnswer":"Помножити 13 подань на ставку."},{"id":"SWP-05","types":["Порахуй"],"states":"[два місячні реєстри й рядок сторно]","input":"[number: два результати]","answer":"[-11 USD, 108 USD]","decision":"віднести сторно до квітневої групи","evidence":"7 дій по 12 USD і коригування 36 USD","nextStep":"звірити травневий переказ","wrongAnswer":"Відняти сторно від зрілої квітневої суми вдруге."}]},"3.9.2":{"prompt":"**SWP-02 · Оціни офер.** A каже «Ви вже виграли» й вимагає $1 за отримання. B приймає безоплатну анкету після відмови від покупки, але для обраної країни ще не звірили місцеві правила. C показує тріал $1, а $9 кожні 30 днів стає видно після платного підтвердження. Запиши рішення, доказ і наступний крок для кожної картки.\n\n**SWP-04 · Діалог.** Менеджер пише: «Без покупки заявка є. Покупка додає ще один шанс. Лишай у звіті “безоплатний розіграш”». Напиши рішення, поясни потрібний доказ і признач повторний контроль.","exercises":[{"id":"SWP-02","types":["Оціни офер"],"states":"[три паперові маршрути]","input":"[select: рішення, text: доказ і наступний крок]","answer":"[A відхилити, B повернути на місцеву звірку, C відхилити версію]","decision":"окремо перевірити участь і оплату","evidence":"зафіксувати екран або факт проходу","nextStep":"місцева звірка або повторний прохід","wrongAnswer":"Пропустити C бо перший платіж видно."},{"id":"SWP-04","types":["Діалог"],"states":"[чат менеджера та два синтетичні проходи]","input":"[text: три речення]","answer":"[пауза, звірка правил і фактичних шансів, повтор класифікації]","decision":"зупинити нову механіку","evidence":"покупка змінює кількість шансів","nextStep":"повторити правову та платформну звірку","wrongAnswer":"Погодити за самим фактом прийняття безоплатної заявки."}]},"3.9.3":{"prompt":"**SWP-03 · Знайди блокер.** Переглянь схему S-34. Познач три проблемні області: заголовок, кнопку й пізній тариф. У журналі є дата відбору після показу екрана, журнал активації тріалу та примітка, що фотографії в каруселі вигадані. Додай окремий рядок про переможців. Для кожного висновку наведи доказ і вкажи контроль наступної версії.","exercises":[{"id":"SWP-03","types":["Знайди блокер"],"states":"[навчальний екран S-34 і журнал]","input":"[select: три області екрана, text: докази рішення і повторний контроль]","answer":"[виграш до відбору, кнопка активує тріал, тариф після натискання, фальшиві переможці]","decision":"зупинити маршрут","evidence":"позначити три області й доказ для каруселі","nextStep":"повторити відмову підтвердження і скасування","wrongAnswer":"Пропустити після перенесення тарифу якщо кнопка й виграш лишилися."}]},"3.10.1":{"prompt":"**ADW-01 · Оціни офер.** AD-A має 12 реєстрацій, шість перших оплат, з яких дві повернули до закриття. Витрати $65. Підтвердження місць показу немає. SW-B має п’ять початків оплати й два зараховані замовлення, витрати $18. Порахуй обидва результати, познач блокер AD-A і назви доказ, потрібний перед повторною оцінкою.\n\n**ADW-04 · Діалог.** Менеджер пише: «Результат +$6, точні місця показу надам потім». У паперовому досьє є лише назва формату. Запиши відповідь із рішенням, потрібним доказом і повторним контролем.","exercises":[{"id":"ADW-01","types":["Оціни офер"],"states":"[дві картки і закриті реєстри]","input":"[number: два результати, select: блокер, text: наступний доказ]","answer":"[7 USD, -2 USD, місця показу не підтверджено, правила джерела і захисний контроль]","decision":"зупинити AD-A","evidence":"окремий фінансовий рядок і відсутні дозволені місця показу","nextStep":"отримати докази джерела й повторити контроль","wrongAnswer":"Масштабувати AD-A через додатний результат."},{"id":"ADW-04","types":["Діалог"],"states":"[звіт і чат менеджера]","input":"[text: три речення]","answer":"[пауза повтору, підтвердити місця показу, повторити контроль маршруту]","decision":"зупинити повтор","evidence":"додатна економіка і невідоме розміщення","nextStep":"звірити джерело і маршрут","wrongAnswer":"Повторити через додатний результат."}]},"3.10.2":{"prompt":"**ADW-02 · Модератор.** Для кожної картки вкажи рішення, доказ і наступну дію.\n\n| Картка | Матеріал |\n|---|---|\n| A | Контрацепція, нейтральний опис, підтверджені маршрут і 18+. |\n| B | Товар для задоволення під нейтральним заголовком. |\n| C | Платний еротичний контент із написом «18+». |\n| D | Оголошення пропонує сексуальні послуги. |\n| E | Контрацепція з кутом про посилення задоволення. |\n| F | Контрацепція, вікове налаштування не видно. |\n| G | Контрацепція в оголошенні, AD-A за кнопкою. |\n| H | Консультація про репродуктивне здоров’я, підтверджені маршрут і 18+. |\n\n**ADW-05 · Модератор.** A: контрацепція, нейтральний креатив, підтверджені 18+ і маршрут. B: до кошика автоматично додано послугу для дорослих. C: креатив і маршрут збігаються, але доказ віку з іншої кампанії. Признач рішення, доказ і наступну перевірку для кожного макета.","exercises":[{"id":"ADW-02","types":["Модератор"],"states":"[вісім текстових карток]","input":"[select: рішення, text: доказ і наступний крок]","answer":"[A передати, B відхилити, C відхилити, D відхилити, E відхилити версію, F повернути, G відхилити версію, H передати]","decision":"оцінити всі картки","evidence":"назвати продукт або суперечність","nextStep":"передати власнику чи повторити контроль","wrongAnswer":"Дозволити C через позначку 18+."},{"id":"ADW-05","types":["Модератор"],"states":"[три макети і докази]","input":"[select: рішення, text: перевірка]","answer":"[A передати, B відхилити, C повернути по доказ]","decision":"розрізнити три стани","evidence":"склад кошика та версія налаштування","nextStep":"звірити кінцевий маршрут або актуальний доказ","wrongAnswer":"Погодити B через нейтральний креатив."}]},"3.10.3":{"prompt":"**ADW-03 · Знайди блокер.** Для британського паперового сервісу потрібна високоефективна перевірка. T-01 пройшов перевірку, T-02 натиснув лише «Мені 18», T-03 отримав помилку провайдера. Каталог відкрився у всіх трьох. Додатково макет журналу передає копію документа в рекламний трекер. Познач проблемні рядки, докази й потрібні повторні проходи.","exercises":[{"id":"ADW-03","types":["Знайди блокер"],"states":"[три синтетичні статуси і схема даних]","input":"[select: проблемні рядки, text: докази і наступна дія]","answer":"[T-02, T-03, передача документа, повторні перевірки після правки]","decision":"зупинити маршрут і потік документа","evidence":"фактичні статуси й схема","nextStep":"повторити три проходи і звірити мінімізацію","wrongAnswer":"Пропустити T-02 через слово 18 на кнопці."}]},"3.11.1":{"prompt":"**SRC-01 · Збери кампанію.** Для навчального офера обери формат, ціль і подію. Авторизація на сторонній допис закінчується до завершення тесту. Витрати $64, звіт TikTok показує шість покупок, партнер зарахував п’ять по $16. Запиши рішення, зрілий результат і перевірку перед стартом.","exercises":[{"id":"SRC-01","types":["Збери кампанію"],"states":"[картка офера, два формати, два звіти]","input":"[select: формат ціль подія, number: результат, text: доказ і перевірка]","answer":"[власний відеокреатив, Sales Website, Purchase, +16 USD, звірити макрос і одну подію]","decision":"обрати умови тесту і формат з правами","evidence":"п’ять зарахувань та строк авторизації","nextStep":"повторити контроль посилання і події","wrongAnswer":"Оцінити тест за шістьма покупками платформи без звірки."}]},"3.11.2":{"prompt":"**SRC-02 · Збери кампанію.** Потрібно виміряти попит за запитами «купити органайзер для столу». У тесті витрачено $80. Google показує сім покупок, партнер підтвердив шість по $16. У тестовій адресі лишився буквальний текст {campaignid}. Обери тип, подію, порахуй зрілий результат і визнач, що треба виправити перед новим тестом.","exercises":[{"id":"SRC-02","types":["Збери кампанію"],"states":"[три формати, звіти і буквальний макрос]","input":"[select: кампанія й подія, number: результат, text: контроль]","answer":"[пошук, Purchase, +16 USD, перевірити підстановку і реєстр]","decision":"пошук під заданий намір","evidence":"шість зарахувань і буквальний макрос","nextStep":"повторити перевірку адреси та події","wrongAnswer":"Помножити сім платформних покупок на ставку."}]},"3.11.3":{"prompt":"**SRC-03 · Діагноз.** Push витратив $48 і має чотири зарахування. Popunder витратив $48 і має два. Ставка $16. У частині рядків push параметр зони лишився буквальним. Порахуй результат обох форматів. Виріши, чи можна прийняти рішення щодо окремої зони push, і назви наступну перевірку.\n\n**SRC-08 · Порахуй.** Навчальний тест popunder: 20 000 показів, $2,50 CPM, ще $6 супутніх витрат. Партнер зарахував три замовлення по $16. Порахуй повні витрати, результат і поріг зарахувань у цілих діях.","exercises":[{"id":"SRC-03","types":["Діагноз"],"states":"[закриті звіти двох форматів, буквальний параметр]","input":"[number: два результати, select: рішення щодо зони, text: доказ і повторна перевірка]","answer":"[+16 USD, -16 USD, відкласти рішення щодо зони, звірити підстановку]","decision":"окремо оцінити формат і зону","evidence":"закриті реєстри і буквальний параметр","nextStep":"повторити контроль посилання","wrongAnswer":"Призначити всі невідомі рядки одній зоні."},{"id":"SRC-08","types":["Порахуй"],"states":"[рахунок за покази і партнерський реєстр]","input":"[number: повні витрати результат і поріг]","answer":"[56 USD, -8 USD, 4 дії]","decision":"оцінити за повними витратами","evidence":"CPM і три зарахування","nextStep":"звірити фінальний статус","wrongAnswer":"Ділити витрати на кількість аукціонних показів і назвати це CPA."}]},"3.11.4":{"prompt":"**SRC-04 · Діагноз.** N-21 витратив $48 і має чотири зарахування. N-22 витратив $36 і має два зарахування та обрізану рекламну позначку. Ставка $16. Порахуй результат кожного сайту і кампанії. Назви доказ і наступну дію щодо N-22.\n\n**SRC-07 · Діалог.** Видавець пише: «На мобільному позначку видно після прокручування. Уже є переходи, тож лишайте показ». Напиши рішення, доказ і контроль після правки.","exercises":[{"id":"SRC-04","types":["Діагноз"],"states":"[два звіти за сайтами і мобільний макет]","input":"[number: три результати, select: рішення, text: доказ і повторна перевірка]","answer":"[+16 USD, -4 USD, +12 USD, зупинити N-22 і повторити перевірку позначення]","decision":"зупинити проблемне розміщення","evidence":"формули і мобільний перегляд","nextStep":"звірити виправлену картку і макрос","wrongAnswer":"Лишити N-22 через додатний результат усієї кампанії."},{"id":"SRC-07","types":["Діалог"],"states":"[чат, мобільний перегляд, рання статистика]","input":"[text: три речення]","answer":"[пауза розміщення, доказ першого екрана, повтор маршруту]","decision":"призупинити розміщення","evidence":"рекламна позначка відсутня на першому екрані","nextStep":"повторити перегляд після правки","wrongAnswer":"Лишити показ через ранні переходи."}]},"3.11.5":{"prompt":"**SRC-05 · Діагноз.** Мережа витратила $80 за 100 установлень, MMP бачить 27 вступів, партнер зарахував 22 по $4. У магазині A дає 30 завантажень зі 150, B — 36 зі 150. У частини записів немає ID застосунку-видавця. Порахуй CPI, результат закупівлі та різницю між сторінками. Познач висновок, який треба відкласти.","exercises":[{"id":"SRC-05","types":["Діагноз"],"states":"[звіти мережі, MMP, партнера й магазину]","input":"[number: CPI результат і різниця, text: обмеження і повторна перевірка]","answer":"[0.80 USD, +8 USD, 4 відсоткові пункти, відкласти оцінку видавця]","decision":"відокремити закупівлю і ASO","evidence":"формули й пропуск ID","nextStep":"звірити макрос і надійність тесту","wrongAnswer":"Визнати B надійно кращою за одним спрощеним зрізом і приписати їй усі +8 USD."}]},"3.11.6":{"prompt":"**SRC-06 · Збери кампанію.** Telegram Ads витратив $48 і дав чотири зарахування. Допис автора коштував $70 і дав п’ять. Ставка $16. У чернетці офіційного текстового оголошення кнопка веде на зовнішній сайт. Визнач два результати, блокер і спосіб окремої звірки джерел.\n\n**SRC-09 · Модератор.** A: кнопка короткого оголошення веде на зовнішній сайт. B: кнопка відкриває релевантний бот, а узгоджений навчальний код працює. C: автор називає оплачений допис незалежною рекомендацією. Для кожного дай рішення, доказ і дію після правки.","exercises":[{"id":"SRC-06","types":["Збери кампанію"],"states":"[два способи розміщення та закриті дані]","input":"[number: два результати, select: блокер, text: перевірка джерел]","answer":"[+16 USD, +10 USD, зовнішнє посилання для цього формату, окремий код або посилання і реєстр]","decision":"зупинити чернетку офіційного формату","evidence":"формули й адреса в кнопці","nextStep":"звірити релевантний напрям і окремі мітки","wrongAnswer":"Використати однаковий код для обох джерел і оцінити їх окремо."},{"id":"SRC-09","types":["Модератор"],"states":"[три макети Telegram]","input":"[select: рішення, text: доказ]","answer":"[A повернути, B передати на фінальну перевірку, C повернути]","decision":"розрізнити маршрут і позначення","evidence":"адреса або статус матеріалу","nextStep":"повторити фактичний перегляд","wrongAnswer":"Погодити всі формати за однаковим текстом."}]},"3.11.F":{"prompt":"**SRC-F · Збери кампанію + Журнал + Порахуй.** Обери пошук, TikTok або native для питання про вже сформований попит. Зафіксуй варіант, який обрав, і поясни, як дані цього джерела допоможуть відповісти на питання. Потім прочитай наданий зріз пошукового тесту. Команда провела його умовно після виправлень, описаних у таблиці.\n\n| Матеріал | Дані для роботи |\n|---|---|\n| Картка | $16 за прийняте оплачене замовлення, група закривається на день 7 |\n| Meta, закрито | $90 витрат, сім зарахувань |\n| Чернетка Google Search | Партнер підтвердив лише Meta. У тестовому журналі після кліка стоїть буквальне campaign_id={campaignid}. |\n| Контроль після правки | Підтверджено Search для цього офера й ринку. Новий прохід показав campaign_id=431 та одну умовну Purchase. |\n| Search, ранній зріз | $72 витрат, 180 кліків, чотири покупки в Google, два партнерські зарахування, група відкрита. |\n| Search, день 7 | Ті самі $72 витрат, сім покупок у Google, шість партнерських зарахувань. Переказів ще немає. |\n\n1. Заповни бриф: ціль, подія, формат, цільовий намір, маршрут і власник перевірки. Запиши, яка фраза запиту відповідає оферу й яка фраза потребує виключення за умовами тесту.\n\n2. Знайди два блокери чернетки. Для кожного зістав очікуване й фактичне, наведи доказ після правки та познач, яку перевірку можна закрити.\n\n3. Порахуй раннє нарахування Search, середній CPC та зрілий підсумок. Порівняй вартість зарахованого замовлення й фінансовий результат із Meta. Для Search окремо підпиши касовий стан.\n\n4. Склади три речення для команди: рішення, доказ і наступний крок. Назви межу висновку за двома групами.\n\n### Перевір, чи рішення відповідає питанню тесту\n\nУ висновку покажи, чи підтверджено право на запуск, чи можна відтворити подію та коли стала доступна зріла економіка. Якщо дані Search вищі за дані Meta за одним показником і нижчі за іншим, запиши обидва. Абсолютний результат залежить від обсягу, а вартість дії допомагає порівняти групи. За близьких підсумків і малого обсягу наступний контроль має повторити умови й зібрати ще один зрілий зріз. Перед рішенням про збільшення витрат звір капу, виплату й доступну касу.\n\nПеред здачею відкрий ранній рядок і перевір, чи не застосовано до нього дані сьомого дня. Ранній зріз підказує, що перевірити в доставці й трекінгу. Закритий потрібен для фінансового рішення. Якщо в звіті платформи є додаткова покупка, познач розбіжність. Підсумок за партнерською карткою спирається на шість зарахувань. Причину сьомої покупки встановлюй за узгодженим звірянням, а до відповіді залиш рядок відкритим.\n\n### Зафіксуй, чого бракує для висновку про попит\n\nЗістав заплановану фразу «купити органайзер для столу» з фактичними пошуковими термінами. Запит «як зробити органайзер із картону» у цьому брифі виходить за межі наміру купити готовий набір. Передай його на перевірку виключень і запиши, яку групу оголошень це зачіпає. У таблиці вправи є підсумок усієї кампанії, тому попроси деталізацію запитів, перш ніж приписувати всі шість замовлень конкретній фразі. Якщо доступний звіт не дає такої розбивки, підпиши висновок на рівні кампанії. Для повторного тесту збережи список запитів, правила зіставлення й дату зрілого зрізу. Такий запис покаже, яке припущення залишилось відкритим після фінансового розрахунку.\n\nПеред масштабуванням запиши, яка капа діє та як її обліковують. Новий кут креативу вважай окремою зміною, яку треба задокументувати перед повтором тесту.\n\n### Типова помилка\n\n**Типова помилка в навчальній ситуації.** Оцінити джерело за ранніми платформними покупками. Збережи їх як проміжний сигнал і дочекайся реєстру тієї самої групи.","exercises":[{"id":"SRC-F","types":["Збери кампанію","Журнал","Порахуй"],"states":"[картка, три джерела, два блокери, ранній і зрілий зрізи]","input":"[select: джерело і ціль, number: витрати й результати, text: журнал і висновок]","answer":"[Search і Purchase, два блокери, 32 USD рано, CPC 0.40 USD, Search +24 USD, Meta +22 USD, каса Search -72 USD]","decision":"Search для попиту і повторна звірка","evidence":"зарахування та два контрольні докази","nextStep":"звірити розбіжність і повторити тест","wrongAnswer":"Назвати Search переможцем для всіх кампаній після однієї групи."}]},"4.1":{"prompt":"**PRO-01 · Діалог.** Відповідай обом відправникам. Лист веде на чужий домен, менеджер просить код. Запиши незалежну перевірку та дві дії, якщо код уже передано.","exercises":[{"id":"PRO-01","types":["Діалог"],"states":"[синтетичний бриф і журнал]","input":"[text: рішення доказ наступний крок]","answer":"[Зупини запит і перевір окремим каналом.]","decision":"Зупини запит і перевір окремим каналом.","evidence":"Код і домен не відповідають звичному процесу.","nextStep":"Відкрий кабінет самостійно, зв’яжися з менеджером через відомий контакт. За компрометації відклич сесії й перевір ролі.","wrongAnswer":"Надіслати код через терміновість."}]},"4.2":{"prompt":"**PRO-02 · День за днем.** Витрати досягли $60. Система бачить 4 події, партнер зарахував одну по $16, ще три відкриті. Друг пропонує додати $40. Запиши дію зараз, статус фінансів і дату перегляду.","exercises":[{"id":"PRO-02","types":["День за днем"],"states":"[синтетичний бриф і журнал]","input":"[text: рішення доказ наступний крок]","answer":"[Постав паузу новим витратам і залиш групу відкритою.]","decision":"Постав паузу новим витратам і залиш групу відкритою.","evidence":"Досягнуто ліміт, $16 є поточним нарахуванням.","nextStep":"На п’ятий день перевір закритий реєстр. Окремий тест потребує нової гіпотези й ліміту.","wrongAnswer":"Додати $40, щоб повернути попередні витрати."}]},"4.3":{"prompt":"**PRO-03 · Оціни офер.** Команда A дає фікс і фінансує тест. B пропонує 20% від бази $150, але збитки й сторно не описані. Порахуй приклад B і сформулюй три уточнення. Назви два матеріали портфоліо.","exercises":[{"id":"PRO-03","types":["Оціни офер"],"states":"[синтетичний бриф і журнал]","input":"[text: рішення доказ наступний крок]","answer":"[За B умовна частка $30. Умови перед рішенням потребують уточнення.]","decision":"За B умовна частка $30. Умови перед рішенням потребують уточнення.","evidence":"База $150 × 20% = $30. Відкриті витрати, сторно й відповідальність за збитки.","nextStep":"Попроси письмові умови й додай до портфоліо два фінали з доказами.","wrongAnswer":"Вибрати B за самим відсотком."}]},"4.4":{"prompt":"**PRO-04 · Модератор.** Познач три рядки: правильна ціна 129 RON, вигаданий відгук і графік доходу без джерела. Запиши рішення для кожного та який доказ додаси після правки.","exercises":[{"id":"PRO-04","types":["Модератор"],"states":"[синтетичний бриф і журнал]","input":"[text: рішення доказ наступний крок]","answer":"[Звір ціну за карткою, відхили відгук і непідтверджений графік.]","decision":"Звір ціну за карткою, відхили відгук і непідтверджений графік.","evidence":"У картці є ціна. Для відгуку й графіка джерел немає.","nextStep":"Повтори контроль усіх елементів і звір чинні правила маркування.","wrongAnswer":"Додати позначку AI та залишити вигаданий доказ."}]},"4.5":{"prompt":"**PRO-05 · Журнал.** Повідомлення каже, що з понеділка змінився макрос усіх трекерів. Офіційний журнал описує один трекер і лише нову версію. Заповни доказ, сферу дії, дату наступної звірки й рішення.","exercises":[{"id":"PRO-05","types":["Журнал"],"states":"[синтетичний бриф і журнал]","input":"[text: рішення доказ наступний крок]","answer":"[Звузь висновок до підтвердженого продукту й версії.]","decision":"Звузь висновок до підтвердженого продукту й версії.","evidence":"Офіційний запис підтверджує лише один трекер.","nextStep":"Перевір підстановку для цієї версії та онови зачеплений шаблон.","wrongAnswer":"Замінити параметри всіх джерел за повідомленням з чату."}]},"4.F":{"prompt":"**PRO-F · Збери кампанію.** Склади власний календар на 30 днів. За умовного бюджету $180 запиши ліміт втрат, вертикаль, ресурси, три гіпотези, пороги паузи, дату дозрівання кожної групи та перевірку каси.","exercises":[{"id":"PRO-F","types":["Збери кампанію"],"states":"[синтетичний бриф і журнал]","input":"[text: рішення доказ наступний крок]","answer":"[Оформи три тести в межах ліміту та окремий резерв.]","decision":"Оформи три тести в межах ліміту та окремий резерв.","evidence":"Приклад $40 + $50 + $50 = $140 і резерв $40. До тестів є контроль доступу та подій.","nextStep":"Перевір, що наступні витрати залежать від доказу та доступної каси.","wrongAnswer":"Витратити резерв після першого негативного зрізу без нової підстави."}]}};
